class OutputBuilder:
    def __init__(self, opts, outfile_obj=None):
        self.opts=opts
        self.lines=[]
        self.cur_file=None
        self.cur_line=1
        self.buf=''
        self.buf_started=False
        self.outfile_obj=outfile_obj  # file handle or None for stdout buffer
    def _marker_text(self, file, line, flags):
        if self.opts.p_mode==1:
            return None
        if self.opts.p_mode==2:
            return f'#line {line} "{file}"'
        s=f'# {line} "{file}"'
        if flags: s+=f' {flags}'
        return s
    def flush_buf(self):
        if self.buf_started:
            self.lines.append(self.buf.rstrip())
            self.buf=''; self.buf_started=False
    def raw_line(self, s):
        self.flush_buf()
        if self.opts.p_mode==1 and s=='':
            return
        self.lines.append(s)
    def marker(self, file, line, flags='', emit_blank_for_old=False, old_line=None):
        # switch segment
        if emit_blank_for_old and self.cur_file is not None:
            # pad out old segment up to old_line inclusive with blanks if not started
            if self.buf_started:
                self.flush_buf(); self.cur_line+=1
            if old_line is not None:
                while self.cur_line<=old_line:
                    if self.opts.p_mode!=1:
                        self.lines.append('')
                    self.cur_line+=1
        else:
            self.flush_buf()
        mt=self._marker_text(file,line,flags)
        if mt is not None:
            self.lines.append(mt)
        self.cur_file=file; self.cur_line=line; self.buf=''; self.buf_started=False
    def _ensure_line(self, file, line):
        if not self.buf_started:
            if file!=self.cur_file:
                self.marker(file,line,'')
                return
            if line>self.cur_line:
                gap=line-self.cur_line
                if gap>8 and self.opts.p_mode!=1:
                    mt=self._marker_text(file,line,'')
                    if mt is not None: self.lines.append(mt)
                    self.cur_line=line
                else:
                    if self.opts.p_mode!=1:
                        for _ in range(gap): self.lines.append('')
                    self.cur_line=line
            elif line<self.cur_line:
                mt=self._marker_text(file,line,'')
                if mt is not None: self.lines.append(mt)
                self.cur_line=line
        else:
            if line>self.cur_line:
                self.flush_buf(); self.cur_line+=1
                self._ensure_line(file,line)
            # line < cur -> stay
    def add_token(self, tok):
        self._ensure_line(tok.file, tok.line)
        if not self.buf_started:
            self.buf=tok.space+tok.text if not tok.from_macro else (tok.space+tok.text)
            self.buf_started=True
        else:
            self.buf+=tok.space+tok.text
    def add_line_content(self, text, file, line):
        self._ensure_line(file,line)
        if not self.buf_started:
            self.buf=text; self.buf_started=True
        else:
            self.buf+=text
    def finish(self):
        self.flush_buf()
        if not self.lines:
            return ''
        return '\n'.join(self.lines)+'\n'
    def get_partial(self):
        # for error cases, return what we have plus flush
        save=list(self.lines); save_buf=self.buf; save_started=self.buf_started
        self.flush_buf()
        s='\n'.join(self.lines)+'\n' if self.lines else ''
        # do not mutate permanently? Keep flushed state is fine
        return s

