class Preprocessor:
    def __init__(self, state, top_display, mode):
        # mode: 'E', 'compile', 'deps'
        self.state=state; self.opts=state.opts if hasattr(state,'opts') else state
        self.top_display=top_display
        self.mode=mode
        self.macros={}
        self.events=[]  # for dM
        self.deps=[]; self.dep_seen=set()
        self.dep_system={}  # display->bool system
        self.expanded_tokens=[]
        self.builder=None
        self.once_files=set()
        self.cond_stack=[]
        self.include_depth=0
        self.counter=0
        self.date_str=None; self.time_str=None
        self._init_macros()
    def _macro_from(self,name,params_str,body_str):
        params=None; variadic=False; var_name='__VA_ARGS__'
        if params_str is not None:
            params=[]
            if params_str.strip():
                for p in [x.strip() for x in params_str.split(',')]:
                    if p=='...': variadic=True
                    elif p.endswith('...'): params.append(p[:-3].strip()); variadic=True; var_name=p[:-3].strip() or '__VA_ARGS__'
                    else: params.append(p)
            body=tokenize_text(body_str,'<command line>',1)
        else:
            body=tokenize_text(body_str,'<command line>',1)
        return Macro(name,params,variadic,var_name,body)
    def _init_macros(self):
        opts=self.opts
        is_c11 = opts.std in ('c11','gnu11')
        stdver='201112L' if is_c11 else '199901L'
        pre=[]
        for name,params,body in BASE_PREDEFS:
            if name=='__GAP__':
                if is_c11:
                    for e in STD_C11_EXTRAS: pre.append(e)
                continue
