        self.buf_started=False
        self.outfile_obj=outfile_obj  # file handle or None for stdout buffer
    def _marker_text(self, file, line, flags):
        if self.opts.p_mode==1:
            return None
        if self.opts.p_mode==2:
            return f'#line {line} "{file}"'
        s=f'# {line} "{file}"'
        if flags: s+=f' {flags}'
        return s
    def flush_buf(self):
        if self.buf_started:
            self.lines.append(self.buf.rstrip())
            self.buf=''; self.buf_started=False
    def raw_line(self, s):
        self.flush_buf()
        if self.opts.p_mode==1 and s=='':
            return
        self.lines.append(s)
    def marker(self, file, line, flags='', emit_blank_for_old=False, old_line=None):
        # switch segment
        if emit_blank_for_old and self.cur_file is not None:
            # pad out old segment up to old_line inclusive with blanks if not started
            if self.buf_started:
                self.flush_buf(); self.cur_line+=1
            if old_line is not None:
                while self.cur_line<=old_line:
                    if self.opts.p_mode!=1:
                        self.lines.append('')
                    self.cur_line+=1
        else:
            self.flush_buf()
        mt=self._marker_text(file,line,flags)
        if mt is not None:
            self.lines.append(mt)
        self.cur_file=file; self.cur_line=line; self.buf=''; self.buf_started=False
    def _ensure_line(self, file, line):
        if not self.buf_started:
            if file!=self.cur_file:
                self.marker(file,line,'')
