        cand=os.path.join(path, filename) if path else filename
        tried.append(cand)
        if os.path.isfile(cand) or os.path.isdir(cand):
            is_system=(kind=='system')
            return cand,is_system
    return None

def _pp_do_include(self, d, ctx, include_next=False):
    opts=self.opts
    eff_line=d.line+ctx.line_offset; eff_file=ctx.logical_file
    rest=d.raw_rest.strip(' \t')
    # strip comments already done in directive cleaned raw_rest? d.rest is stripped cleaned
    rest_clean=d.rest.strip()
    filename=None; quoted=False; extra_toks=[]
    if rest_clean.startswith('"'):
        end=rest_clean.find('"',1)
        if end<0: self._error(eff_file,eff_line,ctx.stack,'missing terminating " character')
        filename=rest_clean[1:end]; quoted=True
        extra=rest_clean[end+1:].strip()
        if extra: opts.warn_at(eff_file,eff_line,ctx.stack,"extra tokens after directive")
    elif rest_clean.startswith('<'):
        end=rest_clean.find('>',1)
        if end<0: self._error(eff_file,eff_line,ctx.stack,'missing terminating > character')
        filename=rest_clean[1:end]; quoted=False
        extra=rest_clean[end+1:].strip()
        if extra: opts.warn_at(eff_file,eff_line,ctx.stack,"extra tokens after directive")
    else:
        # macro expand rest
        toks=tokenize_text(rest_clean, eff_file, eff_line, ctx.stack)
        exp=list(self._expand_segment(toks, ctx))
        s=''.join((t.space if i>0 else '')+t.text for i,t in enumerate(exp)).strip()
        if s.startswith('"'):
            end=s.find('"',1)
            if end<0: self._error(eff_file,eff_line,ctx.stack,'missing terminating " character')
            filename=s[1:end]; quoted=True
        elif s.startswith('<'):
            end=s.find('>',1)
            if end<0: self._error(eff_file,eff_line,ctx.stack,'missing terminating > character')
            filename=s[1:end]; quoted=False
        else:
            self._error(eff_file,eff_line,ctx.stack, '\'#include\' expects "FILENAME" or <FILENAME>')
    resolved=self._resolve_include(filename, quoted, ctx, include_next)
    if resolved is None:
        self._error(eff_file,eff_line,ctx.stack, f"include file '{filename}' not found")
    cand,is_system=resolved
    # record dep
    if cand not in self.dep_seen:
        self.dep_seen.add(cand); self.deps.append(cand); self.dep_system[cand]=is_system
    if os.path.abspath(cand) in self.once_files if cand!='-' else False:
        # still do builder transition? skip content
        if self.mode=='E' and not opts.dM:
            self.builder.marker(cand,1,'1',emit_blank_for_old=True,old_line=eff_line)
            self.builder.marker(ctx.logical_file, eff_line+1, '2')
        return
    try:
        content=read_file_content(opts,cand)
    except Exception:
        self._error(eff_file,eff_line,ctx.stack, f"include file '{filename}' not found")
    child_stack=tuple(list(ctx.stack)+[(eff_file,eff_line)])
    child_ctx=PPContext(cand, child_stack)
    if self.mode=='E' and not opts.dM:
        self.builder.marker(cand,1,'1',emit_blank_for_old=True,old_line=eff_line)
    self._process_content(cand, content, child_ctx)
    if self.mode=='E' and not opts.dM:
        self.builder.marker(ctx.logical_file, eff_line+1, '2')

def _pp_process_include_from(self, inc, top_display, inc_line, marker_line, from_commandline=False):
    # used for -include
    opts=self.opts
    # resolve as quoted? -include file search like quoted from cwd then includes
    ctx_like=PPContext(top_display, ((top_display,0),))
    # use include resolution quoted with curdir = dirname(top)
    resolved=self._resolve_include(inc, True, ctx_like, False)
    if resolved is None:
        self._error('<command line>',inc_line,((top_display,0),), f"include file '{inc}' not found")
    cand,is_system=resolved
    if cand not in self.dep_seen:
        self.dep_seen.add(cand); self.deps.append(cand); self.dep_system[cand]=is_system
    try: content=read_file_content(opts,cand)
    except Exception:
        self._error('<command line>',inc_line,((top_display,0),), f"include file '{inc}' not found")
    child_ctx=PPContext(cand, ((top_display,0),))
    if self.mode=='E' and not opts.dM:
        if opts.dD:
            self.builder.raw_line('')
            self.builder.marker(cand,1,'1')
        else:
            self.builder.marker('<command line>',marker_line,'')
            self.builder.marker(cand,1,'1')
    self._process_content(cand, content, child_ctx)
    if self.mode=='E' and not opts.dM:
        self.builder.marker('<command line>',marker_line,'2')

