def read_file_content(opts, display):
    if display=='-':
        if opts.stdin_used:
            return ''
        opts.stdin_used=True
        data=sys.stdin.buffer.read() if opts.stdin_data is None else opts.stdin_data
        opts.stdin_data=data
        return data.decode('utf-8','surrogateescape')
    if os.path.isdir(display):
        return ''
    with open(display,'rb') as f:
        return f.read().decode('utf-8','surrogateescape')

class PPContext:
    def __init__(self, display, stack):
        self.display=display
        self.logical_file=display
        self.line_offset=0
        self.stack=stack
        self.pack=None

class Preprocessor2:
    pass

# Extend Preprocessor with main methods (assigned below)
def _pp_output_dd_prelude(self):
    b=self.builder; opts=self.opts
    is_c11=opts.std in ('c11','gnu11')
    extras=[e for e in self.predef_list if e[0] in ('__STDC_NO_ATOMICS__','__STDC_NO_COMPLEX__','__STDC_NO_THREADS__','__STDC_UTF_16__','__STDC_UTF_32__')]
    extra_names=set(x[0] for x in extras)
    for name,params,body in self.predef_list:
        if name=='__STDC_NO_ATOMICS__':
            b.raw_line('')
        if name=='__UINTPTR_TYPE__' and not extras:
            for _ in range(8): b.raw_line('')
        b.raw_line(self.format_define_event(name,params,body))
        if name=='__STDC_UTF_32__':
            b.raw_line('')
    if opts.p_mode==0:
        b.raw_line('# 163 "<command line>"')
    elif opts.p_mode==2:
        b.raw_line('#line 163 "<command line>"')
    base_body='"'+self.top_display.replace('\\','\\\\').replace('"','\\"')+'"'
    b.raw_line(f"#define __BASE_FILE__ {base_body}")
    for ev in opts.defines:
        if ev[0]=='D':
            _,name,params,body=ev
            b.raw_line(self.format_define_event(name,params,body))
        else:
            b.raw_line(f"#undef {ev[1]}")

def _pp_active(self):
    return all(fr['active'] for fr in self.cond_stack)

def _pp_error(self, file,line,stack,msg):
    self.opts.error_at(file,line,stack,msg)

def _pp_process_top(self, content):
    opts=self.opts
    if self.mode=='E':
        self.builder=OutputBuilder(opts)
        b=self.builder
        b.marker(self.top_display,1,'')
        b.marker('<command line>',1,'1')
        if opts.dD:
            self._output_dd_prelude()
    # apply commandline macros/includes
    self.process_commandline()
    if self.mode=='E' and not opts.dM:
        self.builder.marker(self.top_display,1,'2')
    ctx=PPContext(self.top_display,())
    self._process_content(self.top_display, content, ctx)
    if self.cond_stack:
        # error reported below by caller context; handled in _process_content end
        pass
    if self.mode=='E':
        if opts.dM:
            return ''
        return self.builder.finish()
    return self.expanded_tokens

def _pp_process_content(self, display, content, ctx):
    scanner=Scanner(content, display, ctx.stack)
    elems=scanner.scan_all()
    base_depth=len(self.cond_stack)
    i=0
    total_lines=len(content.splitlines()) if content else 0
    while i<len(elems):
        el=elems[i]
        if isinstance(el, tuple) and el and el[0]=='error':
            # only raise if active (approximation) and not beyond eof handling
            if self._active():
                line=el[2]+ctx.line_offset
                self._error(ctx.logical_file,line,ctx.stack,el[1])
            i+=1; continue
        if isinstance(el, tuple): # newline
            i+=1; continue
        if isinstance(el, Directive):
            self._handle_directive(el, ctx, base_depth)
            i+=1; continue
        if isinstance(el, Token):
            if el.kind=='eof': break
            if not self._active():
                i+=1; continue
            # gather token segment until directive/eof
            seg=[]; j=i
            while j<len(elems):
                e2=elems[j]
                if isinstance(e2,Directive): break
                if isinstance(e2,Token):
                    if e2.kind=='eof': break
                    # adjust effective file/line
                    t=e2.clone()
                    t.line=e2.line+ctx.line_offset; t.file=ctx.logical_file; t.stack=ctx.stack
                    seg.append(t)
                j+=1
            # expand segment incrementally
            for tok in self._expand_segment(seg, ctx):
                self._emit_token(tok, ctx)
            i=j; continue
        i+=1
    if len(self.cond_stack)>base_depth:
        frame=self.cond_stack[-1]
        kind=frame.get('kind','if')
        msg='missing #endif' if kind=='if' else '#endif expected'
        line=max(1,total_lines)
        self._error(ctx.logical_file,line,ctx.stack,msg)
    elif len(self.cond_stack)<base_depth:
        # extra endif already handled as error
        pass

def _pp_emit_token(self, tok, ctx):
    # _Pragma handling at top level
    if self.mode=='E':
        if self.opts.dM:
            return
        self.builder.add_token(tok)
    else:
        self.expanded_tokens.append(tok)

def _pp_handle_directive(self, d, ctx, base_depth):
    opts=self.opts
    name=d.name
    eff_line=d.line+ctx.line_offset
    eff_file=ctx.logical_file
    # numeric directive as #line
    if name and name[0].isdigit():
        # treat as line directive
        if not self._active(): return
        self._do_line_directive(d, ctx, number=int(name))
        return
    if name=='':
        return
    # conditionals
    if name in ('if','ifdef','ifndef'):
        parent_active=self._active()
        if name=='if':
            val=False
            if parent_active:
                val=self._eval_pp_expr(d.rest, eff_file, eff_line, ctx.stack, 'if')
            self.cond_stack.append({'parent':parent_active,'active':parent_active and bool(val),'taken':parent_active and bool(val),'seen_else':False,'kind':'if'})
        else:
            toks=tokenize_text(d.rest, eff_file, eff_line, ctx.stack)
            if not toks or toks[0].kind!='id':
                self._error(eff_file,eff_line,ctx.stack, f"invalid argument for '#{name}'")
            if len(toks)>1:
                opts.warn_at(eff_file,eff_line,ctx.stack,"extra tokens after directive")
            defined=toks[0].text in self.macros
            val=defined if name=='ifdef' else not defined
            self.cond_stack.append({'parent':parent_active,'active':parent_active and val,'taken':parent_active and val,'seen_else':False,'kind':name})
        return
    if name=='elif':
        if len(self.cond_stack)<=base_depth:
            self._error(eff_file,eff_line,ctx.stack,"#elif without matching #if")
        fr=self.cond_stack[-1]
        if fr.get('seen_else'):
            self._error(eff_file,eff_line,ctx.stack,"#elif after #else")
        if fr['parent'] and not fr['taken']:
            val=self._eval_pp_expr(d.rest, eff_file, eff_line, ctx.stack, 'elif')
            fr['active']=bool(val)
            if val: fr['taken']=True
        else:
            fr['active']=False
        return
    if name=='else':
        if len(self.cond_stack)<=base_depth:
            self._error(eff_file,eff_line,ctx.stack,"#else without matching #if")
        fr=self.cond_stack[-1]
        if fr.get('seen_else'):
            self._error(eff_file,eff_line,ctx.stack,"#else after #else")
        toks=tokenize_text(d.rest, eff_file, eff_line, ctx.stack)
        if toks:
            opts.warn_at(eff_file,eff_line,ctx.stack,"extra tokens after directive")
        fr['seen_else']=True
        fr['active']=fr['parent'] and not fr['taken']
        if fr['active']: fr['taken']=True
        return
    if name=='endif':
        if len(self.cond_stack)<=base_depth:
            self._error(eff_file,eff_line,ctx.stack,"#endif without matching #if")
        toks=tokenize_text(d.rest, eff_file, eff_line, ctx.stack)
        if toks:
            opts.warn_at(eff_file,eff_line,ctx.stack,"extra tokens after directive")
        self.cond_stack.pop()
        return
    if not self._active():
        return
    # other directives
    if name=='define':
        self._do_define(d, ctx)
        return
    if name=='undef':
        toks=tokenize_text(d.rest, eff_file, eff_line, ctx.stack)
        if not toks:
            opts.warn_at(eff_file,eff_line,ctx.stack,"extra tokens after directive"); return
        nm=toks[0].text if toks[0].kind=='id' else None
        if len(toks)>1: opts.warn_at(eff_file,eff_line,ctx.stack,"extra tokens after directive")
        if nm:
            self.apply_undef(nm, eff_file, eff_line, ctx.stack, event=True)
            if self.mode=='E' and opts.dD:
                self.builder.add_line_content(f"#undef {nm}", eff_file, eff_line)
        return
    if name in ('include','include_next'):
        self._do_include(d, ctx, include_next=(name=='include_next'))
        return
    if name=='error':
        msg=d.rest
        self._error(eff_file,eff_line,ctx.stack, f"#error {msg}" if msg else "#error ")
    if name=='warning':
        msg=d.rest
        opts.warn_at(eff_file,eff_line,ctx.stack, f"#warning {msg}" if msg else "#warning ")
        if self.mode=='E' and not opts.dM:
            # directive line blank handled by line sync on next token
            pass
        return
    if name=='line':
        self._do_line_directive(d, ctx, number=None)
        return
    if name=='pragma':
        self._do_pragma(d, ctx)
        return
    if name in ('ident','sccs'):
        opts.warn_at(eff_file,eff_line,ctx.stack, f"ignoring unknown preprocessing directive #{name}")
        return
    # unknown
    opts.warn_at(eff_file,eff_line,ctx.stack, f"ignoring unknown preprocessing directive #{name}")
    return

def _pp_do_line_directive(self, d, ctx, number=None):
    opts=self.opts
    eff_line=d.line+ctx.line_offset
    eff_file=ctx.logical_file
    if number is None:
        toks=tokenize_text(d.rest, eff_file, eff_line, ctx.stack)
        if not toks or toks[0].kind not in ('num',) :
            self._error(eff_file,eff_line,ctx.stack,"wrong #line format")
        number=parse_number_value(toks[0].text)
        if number is None:
            self._error(eff_file,eff_line,ctx.stack,"wrong #line format")
        rest_toks=toks[1:]
    else:
        rest_toks=tokenize_text(d.rest, eff_file, eff_line, ctx.stack)
    filename=None
    extra=False
    if rest_toks:
        if rest_toks[0].kind=='str':
            raw=rest_toks[0].text
            qpos=raw.find('"'); filename=decode_escapes(raw[qpos+1:-1]) if qpos>=0 else raw
            if len(rest_toks)>1: extra=True
        else:
            extra=True
    if filename is not None:
        if not os.path.isabs(filename):
            base_dir=os.path.dirname(ctx.display)
            if base_dir: filename=os.path.join(base_dir, filename)
        new_file=filename
    else:
        new_file=ctx.logical_file
    if extra:
        opts.warn_at(new_file,number,ctx.stack,"extra tokens after directive")
    # adjust offset: next physical line is d.line+1, its logical should be number
    ctx.line_offset = number - (d.line+1)
    old_file=ctx.logical_file
    ctx.logical_file=new_file
    if self.mode=='E' and not opts.dM:
        if new_file!=old_file:
            self.builder.marker(new_file, number, '')
        # else line sync handles padding/marker

def _pp_do_pragma(self, d, ctx):
    opts=self.opts
    eff_line=d.line+ctx.line_offset; eff_file=ctx.logical_file
    rest=d.rest.strip()
    # output in E mode except once
    first=rest.split()[0] if rest.split() else ''
    if self.mode=='E':
        if not opts.dM and first!='once':
            txt="#pragma" + (f" {rest}" if rest else "")
            self.builder.add_line_content(txt, eff_file, eff_line)
    else:
        # pass to parser as pragma token
        self.expanded_tokens.append(Token(rest,'pragma',eff_line,eff_file,ctx.stack,'',False))
    if first=='once':
        # mark current file
        self.once_files.add(os.path.abspath(ctx.display) if ctx.display!='-' else '-')
    # pack handling for parser is via pragma token above (compile mode)

def _pp_do_define(self, d, ctx):
    opts=self.opts
    eff_line=d.line+ctx.line_offset; eff_file=ctx.logical_file
    rest=d.rest
    toks=tokenize_text(rest, eff_file, eff_line, ctx.stack)
    if not toks or toks[0].kind!='id':
        # get first word
        m=re.match(r'\s*(\S+)', rest)
        bad=m.group(1) if m else '\\n'
        if not rest.strip(): bad='\\n'
        self._error(eff_file,eff_line,ctx.stack, f"invalid macro name '{bad}'")
    name=toks[0].text
    idx=1; params=None; variadic=False; var_name='__VA_ARGS__'
    if idx<len(toks) and toks[idx].text=='(' and not toks[idx].space_bool:
        params=[]; idx+=1; closed=False
        if idx<len(toks) and toks[idx].text==')':
            closed=True; idx+=1
        else:
            while idx<len(toks):
                t=toks[idx]
                if t.text=='...':
                    variadic=True; idx+=1
                    if idx<len(toks) and toks[idx].text==')': closed=True; idx+=1; break
                    else: self._error(eff_file,eff_line,ctx.stack,"bad macro parameter list")
                elif t.kind=='id':
                    # named variadic id...
                    if idx+1<len(toks) and toks[idx+1].text=='...':
                        params.append(t.text); variadic=True; var_name=t.text; idx+=2
                        if idx<len(toks) and toks[idx].text==')': closed=True; idx+=1; break
                        else: self._error(eff_file,eff_line,ctx.stack,"bad macro parameter list")
                    params.append(t.text); idx+=1
                    if idx<len(toks) and toks[idx].text==',':
                        idx+=1
                        if idx<len(toks) and toks[idx].text==')':
                            self._error(eff_file,eff_line,ctx.stack,"bad macro parameter list")
                        continue
                    elif idx<len(toks) and toks[idx].text==')':
                        closed=True; idx+=1; break
                    else:
                        self._error(eff_file,eff_line,ctx.stack,"bad macro parameter list")
                else:
                    self._error(eff_file,eff_line,ctx.stack,"bad macro parameter list")
            if not closed:
                # EOF in param list: TCC reports line after file? Use eff line (approx)
                self._error(eff_file,eff_line,ctx.stack,"bad macro parameter list")
    body_toks=toks[idx:] if idx<=len(toks) else []
    # Build macro
    body_str=' '.join(t.text for t in body_toks)  # not used for storage except compare
    new_macro=Macro(name,params,variadic,var_name,[t.clone(file=eff_file,line=eff_line,stack=ctx.stack) for t in body_toks])
    old=self.macros.get(name)
    if old is not None:
        if old.body_text()!=new_macro.body_text() or old.signature()!=new_macro.signature():
            opts.warn_at(eff_file,eff_line,ctx.stack,f"{name} redefined")
            self.events.append(('blank',))
    # events
    if params is None:
        self.events.append(('define',name,None,canonical_body(body_toks)))
    else:
        ps=','.join(params + (['...'] if variadic and var_name=='__VA_ARGS__' else ([var_name+'...'] if variadic else [])))
        self.events.append(('define',name,ps,canonical_body(body_toks)))
    self.macros[name]=new_macro
    if self.mode=='E' and opts.dD:
        if params is None:
            txt=f"#define {name}" + (f" {canonical_body(body_toks)}" if body_toks else "")
        else:
            ps=','.join(params + (['...'] if variadic else []))
            txt=f"#define {name}({ps})" + (f" {canonical_body(body_toks)}" if body_toks else "")
        self.builder.add_line_content(txt, eff_file, eff_line)

def canonical_body(toks):
    out=''
    for t in toks:
        if out and t.space_bool: out+=' '
        out+=t.text
    return out

def _pp_resolve_include(self, filename, quoted, ctx, include_next=False):
    opts=self.opts
    curdir=os.path.dirname(ctx.display) if ctx.display!='-' else ''
    # dirname '' -> ''
    search=opts.include_search(quoted, curdir if quoted else None)
    # For quoted, first entry is curdir (maybe '')
    tried=[]
    skip_next=False
    for path,kind in search:
        if include_next:
            # skip paths up to and including curdir-equivalent on first pass approximation
            pass
        cand=os.path.join(path, filename) if path else filename
        tried.append(cand)
        if os.path.isfile(cand) or os.path.isdir(cand):
            is_system=(kind=='system')
            return cand,is_system
    return None

def _pp_do_include(self, d, ctx, include_next=False):
    opts=self.opts
    eff_line=d.line+ctx.line_offset; eff_file=ctx.logical_file
    rest=d.raw_rest.strip(' \t')
    # strip comments already done in directive cleaned raw_rest? d.rest is stripped cleaned
    rest_clean=d.rest.strip()
    filename=None; quoted=False; extra_toks=[]
    if rest_clean.startswith('"'):
        end=rest_clean.find('"',1)
        if end<0: self._error(eff_file,eff_line,ctx.stack,'missing terminating " character')
        filename=rest_clean[1:end]; quoted=True
        extra=rest_clean[end+1:].strip()
        if extra: opts.warn_at(eff_file,eff_line,ctx.stack,"extra tokens after directive")
    elif rest_clean.startswith('<'):
        end=rest_clean.find('>',1)
        if end<0: self._error(eff_file,eff_line,ctx.stack,'missing terminating > character')
        filename=rest_clean[1:end]; quoted=False
        extra=rest_clean[end+1:].strip()
        if extra: opts.warn_at(eff_file,eff_line,ctx.stack,"extra tokens after directive")
    else:
        # macro expand rest
        toks=tokenize_text(rest_clean, eff_file, eff_line, ctx.stack)
        exp=list(self._expand_segment(toks, ctx))
        s=''.join((t.space if i>0 else '')+t.text for i,t in enumerate(exp)).strip()
        if s.startswith('"'):
            end=s.find('"',1)
            if end<0: self._error(eff_file,eff_line,ctx.stack,'missing terminating " character')
            filename=s[1:end]; quoted=True
        elif s.startswith('<'):
            end=s.find('>',1)
            if end<0: self._error(eff_file,eff_line,ctx.stack,'missing terminating > character')
            filename=s[1:end]; quoted=False
        else:
            self._error(eff_file,eff_line,ctx.stack, '\'#include\' expects "FILENAME" or <FILENAME>')
