        return
    if not self._active():
        return
    # other directives
    if name=='define':
        self._do_define(d, ctx)
        return
    if name=='undef':
        toks=tokenize_text(d.rest, eff_file, eff_line, ctx.stack)
        if not toks:
            opts.warn_at(eff_file,eff_line,ctx.stack,"extra tokens after directive"); return
        nm=toks[0].text if toks[0].kind=='id' else None
        if len(toks)>1: opts.warn_at(eff_file,eff_line,ctx.stack,"extra tokens after directive")
        if nm:
            self.apply_undef(nm, eff_file, eff_line, ctx.stack, event=True)
            if self.mode=='E' and opts.dD:
                self.builder.add_line_content(f"#undef {nm}", eff_file, eff_line)
        return
    if name in ('include','include_next'):
        self._do_include(d, ctx, include_next=(name=='include_next'))
        return
    if name=='error':
        msg=d.rest
        self._error(eff_file,eff_line,ctx.stack, f"#error {msg}" if msg else "#error ")
    if name=='warning':
        msg=d.rest
        opts.warn_at(eff_file,eff_line,ctx.stack, f"#warning {msg}" if msg else "#warning ")
        if self.mode=='E' and not opts.dM:
            # directive line blank handled by line sync on next token
            pass
        return
    if name=='line':
        self._do_line_directive(d, ctx, number=None)
        return
    if name=='pragma':
        self._do_pragma(d, ctx)
        return
    if name in ('ident','sccs'):
        opts.warn_at(eff_file,eff_line,ctx.stack, f"ignoring unknown preprocessing directive #{name}")
        return
    # unknown
    opts.warn_at(eff_file,eff_line,ctx.stack, f"ignoring unknown preprocessing directive #{name}")
    return

def _pp_do_line_directive(self, d, ctx, number=None):
    opts=self.opts
    eff_line=d.line+ctx.line_offset
    eff_file=ctx.logical_file
    if number is None:
        toks=tokenize_text(d.rest, eff_file, eff_line, ctx.stack)
        if not toks or toks[0].kind not in ('num',) :
            self._error(eff_file,eff_line,ctx.stack,"wrong #line format")
        number=parse_number_value(toks[0].text)
        if number is None:
            self._error(eff_file,eff_line,ctx.stack,"wrong #line format")
        rest_toks=toks[1:]
    else:
        rest_toks=tokenize_text(d.rest, eff_file, eff_line, ctx.stack)
    filename=None
    extra=False
    if rest_toks:
        if rest_toks[0].kind=='str':
            raw=rest_toks[0].text
            qpos=raw.find('"'); filename=decode_escapes(raw[qpos+1:-1]) if qpos>=0 else raw
            if len(rest_toks)>1: extra=True
        else:
            extra=True
    if filename is not None:
        if not os.path.isabs(filename):
            base_dir=os.path.dirname(ctx.display)
            if base_dir: filename=os.path.join(base_dir, filename)
