                self._error(eff_file,eff_line,ctx.stack,"bad macro parameter list")
    body_toks=toks[idx:] if idx<=len(toks) else []
    # Build macro
    body_str=' '.join(t.text for t in body_toks)  # not used for storage except compare
    new_macro=Macro(name,params,variadic,var_name,[t.clone(file=eff_file,line=eff_line,stack=ctx.stack) for t in body_toks])
    old=self.macros.get(name)
