            elif op=='^': left=wrap64(left^right)
            elif op=='&': left=wrap64(left&right)
            elif op=='==': left=1 if left==right else 0
            elif op=='!=': left=1 if left!=right else 0
            elif op=='<': left=1 if left<right else 0
