            # grouping if after '(' is '*','(' , identifier not typedef , '['
            nxt=self.peek(1)
            is_group=False
            if nxt.text in ('*','(','['): is_group=True
            elif nxt.kind=='id' and not self.is_typedef_name(nxt.text): is_group=True
            elif nxt.text==')': is_group=False
