                while self.peek().text in ('const','static','volatile','restrict','*'): self.next()
                length=-1
                if self.peek().text!=']':
                    expr=self.parse_const_expr()
                    try: length=self.eval_const(expr)
                    except TCCError: raise
                    if length is not None and length<0:
                        self.err(self.peek(),"invalid array size")
                self.expect(']')
                suffixes.append(lambda base, ln=length: t_array(base, ln))
                continue
