        self.expect('(')
        params=[]; names=[]; variadic=False
        if self.accept(')'):
            return None, False, []
        # void alone
        if self.peek().text=='void' and self.peek(1).text==')':
            self.next(); self.next(); return [], False, []
        # K&R identifier list detection: sequence of ids/commas then ')', and at least 2 entries or (single and not typedef)
        # peek ahead
        save=self.pos
