            if ptype is None:
                # identifier as type? could be param name with implicit int
                if ptok.kind=='id':
                    self.warn(ptok,"type defaults to int")
                    ptype=t_int()
                else:
                    self.err(ptok,"identifier expected")
            pname, pdecl = self.parse_declarator(ptype, abstract_ok=True)
            # adjust array/function params
            if pdecl.kind=='array': pdecl=t_ptr(pdecl.base)
            elif pdecl.kind=='func': pdecl=t_ptr(pdecl)
            params.append(pdecl); names.append(pname)
            self.skip_attributes()
            if self.accept(','):
                if self.peek().text=='...':
                    self.next(); variadic=True; self.expect(')'); break
                continue
