def _parser_parse_external(self):
    tok=self.peek()
    if tok.text=='_Static_assert':
        self.next(); self.expect('(')
        expr=self.parse_const_expr()
        self.expect(',')
        # string
        msg=''
        if self.peek().kind=='str':
            st=self.next().text; q=st.find('"'); msg=decode_escapes(st[q+1:-1]) if q>=0 else ''
        self.expect(')'); 
        if self.accept(';'): pass
        try: v=self.eval_const(expr)
        except: v=1
        if not v: self.err(tok,msg)
        return
    base, storage, is_typedef, is_inline, struct_defined = self.parse_declspecs()
    if self.peek().text==';':
        self.next()
        if not struct_defined:
            # useless type
            if base is not None:
                self.warn(tok,"useless type defines no instances")
        return
    if base is None:
        # missing type: implicit int, next is declarator name
        if self.peek().kind=='id':
            self.warn(tok,"type defaults to int")
            base=t_int()
        else:
            self.err(tok,"identifier expected")
    # declarator list
    first=True
    while True:
        dtok=self.peek()
        name, dtype = self.parse_declarator(base, abstract_ok=False)
        self.skip_attributes()
        # function definition?
        if dtype.kind=='func' and name:
            if self.peek().text=='{' or (dtype.params and self.is_type_start(self.peek())):
                # function def
                self.parse_function_definition(name,dtype,storage,is_inline,dtok)
                return
        # register symbol before initializer
        sym=None
        if is_typedef:
            if name:
                # typedef symbol stored as type
                self.scopes[-1].typedefs[name]=dtype
                # also pseudo var for lookup? Not as var
            # initializer not allowed
            if self.accept('='):
                self.parse_initializer(dtype)
        else:
            if name:
                is_static=(storage=='static')
                is_extern=(storage=='extern')
                if dtype.kind=='func':
                    # function declaration
                    existing=self.lookup_var(name)
                    if existing and existing.type and existing.type.kind=='func':
                        sym=existing
                    else:
                        sym=Symbol(name,dtype,'extern' if not is_static else 'static',defined=False,token=dtok,label=('' ))
                        sym.label=name if not is_static else name
                        self.declare_var(sym); 
                        if len(self.scopes)==1: self.globals.append(sym)
                    sym.storage='static' if is_static else ('extern' if is_extern else 'global')
                else:
                    existing=self.scopes[0].vars.get(name) if len(self.scopes)>0 else None
                    # only top scope global existing
                    if existing is not None and self.scopes[-1] is self.scopes[0]:
                        sym=existing
                        # redefinition check later with init
                    else:
                        label=name
                        sym=Symbol(name,dtype,'static' if is_static else ('extern' if is_extern else 'global'),defined=False,token=dtok,label=label)
                        self.declare_var(sym)
                        if len(self.scopes)==1: self.globals.append(sym)
                if dtype.kind not in ('func',) and is_struct_type(dtype) and dtype.fields is None:
                    self.err(dtok,"initialization of incomplete type")
                if dtype.kind=='void':
                    self.err(dtok,"declaration of void object")
        init=None
        if self.peek().text=='=':
            self.next(); init=self.parse_initializer(dtype)
            if sym is not None:
                if sym.init is not None:
                    self.err(dtok, f"redefinition of '{name}'")
                sym.init=init; sym.defined=True
                if dtype.kind=='array' and dtype.length<0:
                    # determine length from init
                    ln=infer_array_length(dtype, init)
                    if ln is not None:
                        dtype.length=ln; sym.type=dtype
        else:
            if sym is not None and dtype.kind!='func':
                if storage!='extern':
                    sym.defined=True  # tentative counts as defined for bss except extern
                    if sym.storage=='extern': sym.defined=False
                # tentative merge ok
        if sym is not None and dtype.kind=='func':
            # keep type updated
            sym.type=dtype
        if self.accept(','):
            first=False; continue
        if self.peek().text==';':
            self.next(); break
        self.err_expected(self.peek(),';')
        break

def infer_array_length(dtype, init):
    if init is None: return None
    if init[0]=='init_list':
        return len(init[2])
    if init[0]=='init_expr' and init[2] and init[2][0]=='str':
        # string literal length incl null
        s=node_string_value(init[2])
        return len(s)+1
    return None

def node_string_value(node):
    # node str: return decoded string (without prefix)
    text=node[2] if len(node)>2 else ''
    # token is at node[1]; node format for str will be ('str',tok,value)
    return text

def _parser_parse_function_definition(self, name, dtype, storage, is_inline, dtok):
    # K&R param type declarations
    if self.peek().text!='{':
        # parse declarations until {
        # params names from dtype.param_names
        while self.peek().text!='{' and not self.at_eof():
            # declaration for param
            pbase, pstorage, _, _, _ = self.parse_declspecs()
            if pbase is None: pbase=t_int()
            while True:
                pname, ptype = self.parse_declarator(pbase, abstract_ok=True)
                if pname and dtype.params is not None:
                    if pname in dtype.param_names:
                        idx=dtype.param_names.index(pname); dtype.params[idx]=ptype
                if self.accept(','): continue
                break
            self.expect(';')
    # create function symbol
    existing=self.scopes[0].vars.get(name)
    sym=None
    if existing is not None:
        if existing.defined and existing.type and existing.type.kind=='func':
            self.err(dtok, f"redefinition of '{name}'")
        sym=existing; sym.type=dtype
    else:
        sym=Symbol(name,dtype,'static' if storage=='static' else 'global',defined=False,token=dtok,label=name)
        self.scopes[0].vars[name]=sym; self.globals.append(sym)
    sym.defined=True; sym.is_inline=is_inline
    if storage=='static': sym.storage='static'
    # push scope for params
    self.push_scope()
    param_syms=[]
    params=dtype.params or []
    names=dtype.param_names or []
    for i,ptype in enumerate(params):
        pname=names[i] if i<len(names) else ''
        if pname:
            psym=Symbol(pname,ptype,'param',defined=True,token=dtok)
            self.declare_var(psym); param_syms.append(psym)
        else:
            # unnamed param still need slot
            psym=Symbol('',ptype,'param',defined=True,token=dtok); param_syms.append(psym)
    # variadic unnamed?
    prev_func=self.current_func; prev_sym=self.current_func_sym
    self.current_func_sym=sym
    func_node=('funcdef',dtok,sym,param_syms,None)  # body filled
    self.current_func={'sym':sym,'params':param_syms,'locals':list(param_syms),'temps':[],'labels':{},'all_locals':list(param_syms)}
    body=self.parse_compound_statement()
    func_node=('funcdef',dtok,sym,param_syms,body)
    self.functions.append(func_node)
    self.current_func=prev_func; self.current_func_sym=prev_sym
    self.pop_scope()

def _parser_parse_initializer(self, dtype):
    tok=self.peek()
    if tok.text=='{':
        self.next(); entries=[]
        if self.accept('}'):
            return ('init_list',tok,entries)
        while True:
            # designator
            path=[]
            while self.peek().text in ('.','['):
                if self.peek().text=='.':
                    self.next(); ft=self.peek(); 
                    if ft.kind!='id': self.err(ft,"identifier expected")
                    path.append(('field',self.next().text))
                else:
                    self.next(); e=self.parse_const_expr(); path.append(('index',e)); self.expect(']')
            if path:
                self.expect('=')
                val=self.parse_initializer(dtype)
                entries.append((path,val))
            else:
                val=self.parse_initializer(dtype)
                entries.append((None,val))
            if self.accept(','):
                if self.peek().text=='}': self.next(); break
                continue
            self.expect('}'); break
        return ('init_list',tok,entries)
    else:
        expr=self.parse_assignment_expr()
        return ('init_expr',tok,expr)

Parser.parse_external=_parser_parse_external
Parser.parse_function_definition=_parser_parse_function_definition
Parser.parse_initializer=_parser_parse_initializer

