def _p_parse_const_expr(self):
    return self.parse_conditional_expr()
def _p_parse_assignment_expr(self):
    return self.parse_assign_expr()
def _p_parse_expression(self):
    node=self.parse_assign_expr()
    while self.peek().text==',':
        tok=self.next(); rhs=self.parse_assign_expr(); node=('comma',tok,node,rhs)
    return node
def _p_parse_assign_expr(self):
    node=self.parse_conditional_expr()
    if self.peek().text in ('=','+=','-=','*=','/=','%=','<<=','>>=','&=','^=','|='):
        tok=self.next(); op=tok.text; rhs=self.parse_assign_expr()
        return ('assign',tok,op,node,rhs)
    return node
def _p_parse_conditional_expr(self):
    node=self.parse_binary_expr(0)
    if self.peek().text=='?':
        tok=self.next()
        if self.peek().text==':':
            true_expr=None
        else:
            true_expr=self.parse_expression()
        self.expect(':')
        false_expr=self.parse_conditional_expr()
        return ('cond',tok,node,true_expr,false_expr)
    return node

BIN_LEVELS=[
    ['||'],
    ['&&'],
    ['|'],
    ['^'],
    ['&'],
    ['==','!='],
    ['<','<=','>','>='],
    ['<<','>>'],
    ['+','-'],
    ['*','/','%'],
]
def _p_parse_binary_expr(self, level):
    if level>=len(BIN_LEVELS):
        return self.parse_cast_expr()
    node=self.parse_binary_expr(level+1)
    while self.peek().text in BIN_LEVELS[level]:
        tok=self.next(); op=tok.text; rhs=self.parse_binary_expr(level+1)
        node=('binary',tok,op,node,rhs)
    return node

def _p_parse_cast_expr(self):
    # cast: '(' type ')' cast  or '(' type ')' '{' init '}' compound
    if self.peek().text=='(':
        save=self.pos
        # peek if type start after '('
        if self.is_type_start(self.peek(1)) or self.peek(1).text in ('*','('):
            tok=self.next()
            try:
                base,_,_,_,_=self.parse_declspecs()
                if base is None: raise ValueError("notype")
                name,dtype=self.parse_declarator(base, abstract_ok=True)
            except Exception:
                self.pos=save; return self.parse_unary_expr()
            if self.peek().text!=')':
                self.pos=save; return self.parse_unary_expr()
            self.next()
            if self.peek().text=='{':
                init=self.parse_initializer(dtype)
                return ('compound',tok,dtype,init)
            operand=self.parse_cast_expr()
            return ('cast',tok,dtype,operand)
    return self.parse_unary_expr()

def _p_parse_unary_expr(self):
    tok=self.peek()
    if tok.text in ('++','--'):
        self.next(); operand=self.parse_unary_expr(); return ('preinc',tok,tok.text,operand)
    if tok.text in ('&','*','+','-','~','!'):
        self.next(); operand=self.parse_cast_expr(); return ('unary',tok,tok.text,operand)
    if tok.text=='sizeof':
        self.next()
        if self.peek().text=='(' and (self.is_type_start(self.peek(1)) or self.peek(1).text in ('*','(')):
            save=self.pos
            self.next()
            try:
                base,_,_,_,_=self.parse_declspecs()
                if base is None: raise ValueError()
                name,dtype=self.parse_declarator(base, abstract_ok=True)
                if self.peek().text!=')': raise ValueError()
                self.next()
                return ('sizeof_type',tok,dtype)
            except Exception:
                self.pos=save
                # fallthrough to expression in parens
                operand=self.parse_unary_expr(); return ('sizeof_expr',tok,operand)
        else:
            operand=self.parse_unary_expr(); return ('sizeof_expr',tok,operand)
    if tok.text in ('_Alignof','__alignof','__alignof__'):
        self.next()
        if self.peek().text=='(' and (self.is_type_start(self.peek(1)) or self.peek(1).text in ('*','(')):
