            self.next(); args=[]
            if self.peek().text!=')':
                while True:
                    # special va_arg second argument is type - handled in primary special? For generic call to __builtin_va_arg, intercept
                    args.append(self.parse_assignment_expr())
                    if self.accept(','): continue
                    break
            self.expect(')')
            # special builtins with type args are intercepted elsewhere; generic
            node=('call',tok,node,args); continue
        if tok.text in ('.','->'):
            self.next(); ft=self.peek()
            if ft.kind!='id': self.err(ft,"identifier expected")
            fname=self.next().text
            node=('member',tok,node,fname, tok.text=='->'); continue
        if tok.text in ('++','--'):
            self.next(); node=('postinc',tok,tok.text,node); continue
