def _p_parse_primary_expr(self):
    tok=self.peek()
    if tok.kind=='num':
        self.next(); v=parse_number_value(tok.text)
        return ('num',tok, v if v is not None else 0)
    if tok.kind=='fnum':
        self.next()
        try: fv=float(re.sub(r'[fFlL]+$','',tok.text))
        except: fv=0.0
        # hex float?
        return ('fnum',tok,fv)
    if tok.kind=='char':
        self.next(); return ('num',tok,parse_char_value(tok.text))
    if tok.kind=='str':
        self.next()
        # separate prefix
        raw=tok.text
        # find quote
        qi=raw.find('"'); prefix=raw[:qi] if qi>0 else ''
        content=decode_escapes(raw[qi+1:-1]) if qi>=0 else ''
        # adjacent string concatenation handled in postfix? Strings concatenation in primary loop
        while self.peek().kind=='str':
            t2=self.next(); qi=t2.text.find('"'); content+=decode_escapes(t2.text[qi+1:-1]) if qi>=0 else ''
        return ('str',tok,content,raw,prefix)
    if tok.text=='(':
        self.next(); node=self.parse_expression(); self.expect(')'); return node
    if tok.kind=='id':
        name=tok.text
        # builtins with type arguments
        if name=='__builtin_va_arg':
            self.next(); self.expect('('); expr=self.parse_assignment_expr(); self.expect(',')
            base,_,_,_,_=self.parse_declspecs()
            if base is None: self.err(tok,"identifier expected")
            nm,dtype=self.parse_declarator(base,abstract_ok=True); self.expect(')')
            return ('va_arg',tok,expr,dtype)
        if name=='__builtin_offsetof':
            self.next(); self.expect('('); base,_,_,_,_=self.parse_declspecs(); nm,dtype=self.parse_declarator(base,abstract_ok=True); self.expect(',')
            # member designator: sequence .id / [expr]
            off=0; cur=dtype
            while True:
                if self.accept('.'):
                    ft=self.next(); fld=find_field(cur,ft.text); 
                    if fld is None: self.err(ft,f"field not found: {ft.text}")
                    off+=fld.offset; cur=fld.type; continue
                if self.accept('['):
                    e=self.parse_const_expr(); v=self.eval_const(e); self.expect(']')
                    off+=v*type_size(cur.base); cur=cur.base; continue
                break
            self.expect(')'); return ('num',tok,off)
        if name in ('__func__','__FUNCTION__'):
            self.next()
            fname=self.current_func_sym.name if self.current_func_sym else ''
            return ('str',tok,fname,f'"{fname}"','')
        self.next()
        sym=self.lookup_var(name)
        if sym is None:
            # could be typedef used incorrectly, or undeclared
            if self.peek().text=='(':
