        if sym.storage=='enum':
            return ('num',tok,sym.const_value)
        return ('id',tok,sym)
    # unexpected token
    if tok.kind=='eof':
        self.err(tok,"expression expected at end of input")
    self.err(tok, f"expression expected before '{tok.text}'")

