def _p_parse_compound_statement(self):
    tok=self.expect('{')
    self.push_scope()
    stmts=[]
    while self.peek().text!='}' and not self.at_eof():
        if self.peek().kind=='pragma': self.handle_pragma(self.next()); continue
        st=self.parse_statement()
        if st: stmts.append(st)
    self.expect('}')
    self.pop_scope()
    return ('block',tok,stmts)

