    t=self.peek()
    if t.text in TYPE_KEYWORDS or t.text in STORAGE_KEYWORDS or t.text in QUAL_KEYWORDS: return True
    if t.text in ('_Static_assert',): return True
    if t.kind=='id' and self.is_typedef_name(t.text): return True
    return False

