    if t.kind=='bool': return 1 if v else 0
    sz=type_size(t)
    if sz>=8: return wrap64(v)
    bits=sz*8
    v&= (1<<bits)-1
    if t.signed and v>= (1<<(bits-1)): v-=(1<<bits)
    return v

def eval_const_node(parser, node):
    if node is None: return None
    tag=node[0]
    if tag=='num': return node[2]
    if tag=='fnum': return node[2]
    if tag=='str':
        return None
    if tag=='id':
        sym=node[2]
        if isinstance(sym,Symbol):
            if sym.const_value is not None: return sym.const_value
            if sym.init and sym.storage in ('global','static','static_local'):
                # const global initializer maybe
                if sym.init[0]=='init_expr': return eval_const_node(parser, sym.init[2])
            return None
        return None
    if tag=='unary':
        op=node[2]; v=eval_const_node(parser,node[3])
        if v is None: return None
        if op=='-': return -v
        if op=='+': return v
        if op=='~': return ~v
        if op=='!': return 0 if v else 1
        return None
    if tag in ('preinc','postinc'): return None
    if tag=='binary':
        op=node[2]; a=eval_const_node(parser,node[3]); b=eval_const_node(parser,node[4])
        if op=='&&':
            return 1 if (a and b) else 0 if (a is not None and b is not None) else None
        if op=='||':
            return 1 if (a or b) else 0 if (a is not None and b is not None) else None
        if a is None or b is None: return None
        try:
            if op=='+': return a+b
            if op=='-': return a-b
            if op=='*': return a*b
            if op=='/': return int(a/b) if b!=0 else None
            if op=='%': return a - int(a/b)*b if b!=0 else None
            if op=='<<': return a<<b
            if op=='>>': return a>>b
            if op=='<': return 1 if a<b else 0
            if op=='<=': return 1 if a<=b else 0
            if op=='>': return 1 if a>b else 0
            if op=='>=': return 1 if a>=b else 0
            if op=='==': return 1 if a==b else 0
            if op!=': return 1 if a!=b else 0
            if op=='&': return a&b
            if op=='|': return a|b
            if op=='^': return a^b
        except Exception: return None
        return None
    if tag=='cond':
        c=eval_const_node(parser,node[2])
        if c is None: return None
        if c: return eval_const_node(parser,node[3]) if node[3] is not None else c
        else: return eval_const_node(parser,node[4])
    if tag=='comma': return eval_const_node(parser,node[3])
    if tag=='cast':
        v=eval_const_node(parser,node[3])
        if v is None: return None
        t=node[2]
        if is_float_type(t): return float(v)
        if is_int_type(t) or t.kind=='ptr': return wrap_to_type(int(v), t if t.kind!='ptr' else t_long())
        return v
    if tag=='sizeof_type': return type_size(node[2])
    if tag=='sizeof_expr':
        t=infer_type(parser,node[2])
        return type_size(t)
    if tag=='alignof_type': return type_align(node[2])
    if tag=='alignof_expr':
        t=infer_type(parser,node[2]); return type_align(t)
    if tag=='member':
        # constant struct? not
        return None
    if tag=='index':
        # string literal index
        if node[2][0]=='str':
            idx=eval_const_node(parser,node[3])
            s=node[2][2]
            if idx is not None and 0<=idx<len(s): return ord(s[idx])
            if idx==len(s): return 0
        return None
    if tag=='assign': return eval_const_node(parser,node[4])
    return None

def infer_type(parser, node):
    if node is None: return t_int()
    tag=node[0]
    if tag=='num': 
        v=node[2]
        return t_long() if v>2147483647 or v<-2147483648 else t_int()
    if tag=='fnum': return t_double()
    if tag=='str':
        prefix=node[4] if len(node)>4 else ''
        if prefix=='L': return t_array(t_int(), len(node[2])+1)
        return t_array(t_char(), len(node[2])+1)
    if tag=='id':
        sym=node[2]
        return sym.type if isinstance(sym,Symbol) and sym.type else t_int()
    if tag=='unary':
        op=node[2]; ot=infer_type(parser,node[3])
        if op=='&': return t_ptr(ot)
        if op=='*':
            dt=decay(ot)
            return dt.base if dt.kind=='ptr' else t_int()
        if op=='!': return t_int()
        if op in ('-','+','~'):
            # promotion
            if ot.kind in ('bool','char','short','enum'): return t_int()
            return ot
        return ot
    if tag in ('preinc','postinc'):
        return infer_type(parser,node[3])
    if tag=='binary':
        op=node[2]; lt=infer_type(parser,node[3]); rt=infer_type(parser,node[4])
        if op in ('&&','||','==','!=','<','<=','>','>='): return t_int()
        ld=decay(lt); rd=decay(rt)
        if ld.kind=='ptr' and is_int_type(rd): return ld
        if rd.kind=='ptr' and is_int_type(ld): return rd
        if ld.kind=='ptr' and rd.kind=='ptr': return t_long()
        return usual_type(ld,rd)
    if tag=='assign': return infer_type(parser,node[3])
    if tag=='cond':
        tt=infer_type(parser,node[3]) if node[3] is not None else infer_type(parser,node[2])
        ft=infer_type(parser,node[4])
        td=decay(tt); fd=decay(ft)
        if td.kind=='ptr' or fd.kind=='ptr': return td if td.kind=='ptr' else fd
        if is_struct_type(tt) and is_struct_type(ft): return tt
        return usual_type(td,fd)
    if tag=='comma': return infer_type(parser,node[3])
    if tag=='call':
        ft=infer_type(parser,node[2]); dt=decay(ft)
        if dt.kind=='ptr' and dt.base and dt.base.kind=='func': return dt.base.base
        if ft.kind=='func': return ft.base
        return t_int()
    if tag=='member':
        ot=infer_type(parser,node[2])
        if node[4]: # arrow
            dt=decay(ot); ot=dt.base if dt.kind=='ptr' else ot
        fld=find_field(ot,node[3])
        if fld is None:
            tok=node[1]; parser.opts.error_at(tok.file,tok.line,tok.stack, f"field not found: {node[3]}")
        return fld.type
    if tag=='index':
        at=infer_type(parser,node[2]); dt=decay(at)
        if dt.kind=='ptr': return dt.base
        return t_int()
    if tag=='cast': return node[2]
    if tag in ('sizeof_type','sizeof_expr','alignof_type','alignof_expr'): return t_long(False)
    if tag=='compound': return node[2]
    if tag=='va_arg': return node[3]
    return t_int()

Parser.eval_const=lambda self,node: eval_const_node(self,node)
Parser.infer_type=lambda self,node: infer_type(self,node)

