# ---------------- Code generation ----------------
class AsmError(TCCError): pass

class CodeGen:
    def __init__(self, opts, parser):
        self.o=opts; self.p=parser
        self.lines=[]; self.label_counter=0
        self.string_labels={}  # id(node)->label
        self.float_labels={}
        self.func=None; self.func_sym=None
        self.frame_size=0
        self.local_offsets={}
        self.temps=[]  # list of (offset,size,align,type)
        self.temp_offsets={}
        self.break_stack=[]; self.continue_stack=[]; self.switch_stack=[]
        self.return_label=None
        self.sret_offset=None
        self.reg_save_offset=None
        self.alloca_count=0
    def emit(self,s=''):
        self.lines.append(s)
    def new_label(self,prefix='.L'):
        self.label_counter+=1; return f"{prefix}{self.label_counter}"
    def collect_literals(self):
        # walk all function bodies and global inits for strings / float constants is done on demand during gen (labels created then, but text segment order irrelevant as we emit rodata at end)
        pass
    def string_label(self,node):
        key=id(node)
        if key in self.string_labels: return self.string_labels[key]
        lbl=f".Lstr{len(self.string_labels)}"
        self.string_labels[key]=lbl; return lbl
    def generate(self):
        o=self.o; p=self.p
        self.emit('.text')
        for func in p.functions:
            self.gen_function(func)
        # data
        self.emit_data()
        # literals
        if self.string_labels:
            self.emit('.section .rodata')
            # string labels dict is filled during function/data generation; but we emitted .text first then functions use labels defined later - assembler ok.
            # However dict may be updated during data gen above; now emit all.
            for node_id,lbl in list(self.string_labels.items()):
                # find node string by stored map value tuple
                pass
        # We need string contents: stored in map2
        for lbl,(content,prefix) in getattr(self,'string_data',{}).items():
            self.emit(f"{lbl}:")
            if prefix=='L':
                for ch in content: self.emit(f"    .long {ord(ch)}")
                self.emit("    .long 0")
            else:
                bs=content.encode('utf-8','surrogateescape')
                if bs:
                    self.emit("    .byte "+",".join(str(b) for b in bs))
                self.emit("    .byte 0")
        for lbl,val in getattr(self,'float_data',{}).items():
            self.emit('.align 8')
            self.emit(f"{lbl}:")
            self.emit(f"    .double {repr(val)}")
        return "\n".join(self.lines)+"\n"
    # helpers for literals
    def get_string_label(self,node):
        if not hasattr(self,'string_data'): self.string_data={}
        key=id(node)
        if key in self.string_labels: return self.string_labels[key]
        lbl=f".Lstr{len(self.string_labels)}"; self.string_labels[key]=lbl
        self.string_data[lbl]=(node[2], node[4] if len(node)>4 else '')
        return lbl
    def get_float_label(self,val):
        if not hasattr(self,'float_data'): self.float_data={}
        for lbl,v in self.float_data.items():
            if v==val: return lbl
        lbl=f".Ldbl{len(self.float_data)}"; self.float_data[lbl]=val; return lbl
    # data
    def emit_data(self):
        p=self.p
        # globals in order
        emitted=set()
        for sym in p.globals:
            if sym.type is None: continue
            if sym.type.kind=='func': continue
            if sym.storage=='extern' and sym.init is None: continue
            if sym in emitted: continue
            emitted.add(sym)
            label=sym.label or sym.name
            if sym.storage=='static' or sym.storage=='static_local':
                asm_label=label if label.startswith('__static') or '.' in label else f"{label}"
                # static symbols are local: label as is but not glbl. Use unique if needed
                if sym.storage=='static_local': asm_label=label
                else: asm_label=label
            else:
                asm_label=apply_leading_underscore(self.o, label)
            sym.asm_label=asm_label
            # determine init data
            if sym.init is not None:
                data, relocs = build_data(self, sym.type, sym.init)
                self.emit('.data')
                self.emit(f"    .align {max(1,type_align(sym.type))}")
                if sym.storage not in ('static','static_local'):
                    self.emit(f"    .globl {asm_label}")
                self.emit(f"    .type {asm_label}, @object")
                self.emit(f"    .size {asm_label}, {type_size(sym.type)}")
                self.emit(f"{asm_label}:")
                emit_data_bytes(self, data, relocs)
            else:
                # tentative / bss
                if sym.storage=='extern': continue
                if self.o.flags.get('common') and sym.storage=='global':
                    self.emit(f"    .comm {asm_label},{type_size(sym.type)},{type_align(sym.type)}")
                else:
                    self.emit('.bss')
                    self.emit(f"    .align {max(1,type_align(sym.type))}")
                    if sym.storage not in ('static','static_local'):
                        self.emit(f"    .globl {asm_label}")
                    self.emit(f"    .type {asm_label}, @object")
                    self.emit(f"    .size {asm_label}, {type_size(sym.type)}")
                    self.emit(f"{asm_label}:")
                    self.emit(f"    .zero {type_size(sym.type)}")
    # function
    def gen_function(self, func):
        _,tok,sym,param_syms,body=func
        self.func_sym=sym; self.func={'sym':sym,'params':param_syms}
        # collect locals: parser stored all_locals in? We stored in Parser.current_func at parse time but replaced. Need gather from body AST symbols in decl nodes and params.
        locals_list=list(param_syms)
        self.collect_decl_symbols(body, locals_list)
        # temps
        self.temps=[]; self.temp_offsets={}
        self.collect_temps(body, sym.type.base if sym.type.kind=='func' else t_int())
        # layout frame
        offset=0
        self.local_offsets={}
        # return struct hidden + reg save area reserve later adjust?
        ret_type=sym.type.base if sym.type.kind=='func' else t_int()
        frame_items=[]
        # sret slot (8 bytes)
        self.sret_offset=None
        if is_struct_type(ret_type) and type_size(ret_type)>16:
            offset+=8; self.sret_offset=offset; frame_items.append(('sret',offset))
        if sym.type.variadic:
            # reg save area 304 bytes
            offset=align_up(offset,16); self.reg_save_offset=offset+304  # store as end? We'll use base offset semantics below.
            # We'll represent offsets as distance from rbp: variable at [rbp - off]
            # reg save base = offset+304
            offset+=304; self.reg_save_base=offset
        else:
            self.reg_save_base=None
        # params home and locals
        for s in locals_list:
            if s.type is None: continue
            sz=max(8, align_up(type_size(s.type),8)) if s.storage=='param' and not is_struct_type(s.type) else align_up(max(1,type_size(s.type)), type_align(s.type) if type_align(s.type)<=8 else 8)
            # For params, allocate at least size aligned to 8 for register save simplicity except struct
            if s.storage=='param':
                sz=align_up(max(1,type_size(s.type)),8)
            offset=align_up(offset, min(8,max(1,type_align(s.type))))
            offset+=sz; self.local_offsets[id(s)]=offset; s.offset=offset
        for (toff,tsz,tt) in self.temps:
            offset=align_up(offset, min(8,max(1,type_align(tt))))
            offset+=align_up(max(1,tsz),8); self.temp_offsets[toff]=offset
        self.frame_size=align_up(offset,16)
        label=sym.label or sym.name
        asm_label=label if sym.storage=='static' else apply_leading_underscore(self.o,label)
        sym.asm_label=asm_label
        self.emit(f"    .globl {asm_label}" if sym.storage!='static' else "")
        if self.lines and self.lines[-1]=='': self.lines.pop()
        self.emit(f"    .type {asm_label}, @function")
        self.emit(f"{asm_label}:")
        self.emit("    push %rbp")
        self.emit("    mov %rsp, %rbp")
        if self.frame_size: self.emit(f"    sub ${self.frame_size}, %rsp")
        self.return_label=self.new_label('.Lret')
        # store params
        self.store_params(sym,param_syms,ret_type)
        # body
        self.break_stack=[]; self.continue_stack=[]; self.switch_stack=[]
        self.gen_stmt(body)
        # check labels defined is handled by assembler, but TCC error for undefined label: we track in gen_stmt goto.
        # verify gotos
        for name, gtoks in getattr(self,'goto_refs',{}).items():
            if name not in getattr(self,'labels_defined',{}):
                t=gtoks[0]; self.o.error_at(t.file,t.line,t.stack, f"label '{name}' used but not defined")
        self.emit(f"{self.return_label}:")
        self.emit("    leave")
        self.emit("    ret")
        self.goto_refs={}; self.labels_defined={}
    def collect_decl_symbols(self, node, lst):
        if node is None: return
        if isinstance(node,tuple):
            if node[0]=='decl_stmt':
                for d in node[2]:
                    if d[0]=='decl_local':
                        if d[2] not in lst: lst.append(d[2])
                # also recurse inits
                for d in node[2]:
                    if d[3]: self.collect_decl_symbols(d[3],lst)
                return
            for x in node[1:]:
                self.collect_decl_symbols(x,lst)
        elif isinstance(node,list):
            for x in node: self.collect_decl_symbols(x,lst)
    def collect_temps(self,node,ret_type):
        if node is None: return
        if isinstance(node,tuple):
            # struct producing nodes
            if node[0] in ('call','compound','cond','assign'):
                try:
                    tt=infer_type(self.p,node)
                    if is_struct_type(tt):
                        key=id(node); sz=type_size(tt); self.temps.append((key,sz,tt))
                except Exception: pass
            for x in node[1:]: self.collect_temps(x,ret_type)
        elif isinstance(node,list):
            for x in node: self.collect_temps(x,ret_type)
    def temp_offset(self,node):
