def _cg_store_reg_to(self, reg, addr, typ):
    if is_float_type(typ):
        op='movss' if typ.kind=='float' else 'movsd'
        self.emit(f"    {op} {reg}, {addr}"); return
    sz=type_size(typ)
    if typ.kind=='ptr' or sz>=8:
        self.emit(f"    mov {reg}, {addr}")
    else:
        rv=reg_variant(reg,sz)
        op={1:'movb',2:'movw',4:'movl'}.get(sz,'mov')
        self.emit(f"    {op} {rv}, {addr}")

def _cg_load_from_addr(self, typ):
    # address in %rax, load value into rax/xmm0
    if is_float_type(typ):
        op='movss' if typ.kind=='float' else 'movsd'
        self.emit(f"    {op} (%rax), %xmm0"); return
    if is_struct_type(typ):
