    elif sz==1:
        self.emit("    movsbq (%rax), %rax" if typ.signed else "    movzbq (%rax), %rax")
    else:
        self.emit("    mov (%rax), %rax")

def _cg_normalize(self, typ):
    if typ is None or is_float_type(typ) or is_struct_type(typ): return
    if typ.kind=='ptr': return
    sz=type_size(typ)
    if typ.kind=='bool':
        self.emit("    test %rax, %rax"); self.emit("    setne %al"); self.emit("    movzbq %al, %rax"); return
    if sz==1: self.emit("    movsbq %al, %rax" if typ.signed else "    movzbq %al, %rax")
    elif sz==2: self.emit("    movswq %ax, %rax" if typ.signed else "    movzwq %ax, %rax")
    elif sz==4: 
        if typ.signed: self.emit("    movsxd %eax, %rax") if False else self.emit("    cltq")
        else: self.emit("    mov %eax, %eax")

