def _cg_convert(self, src, dst):
    if dst is None or src is None: return
    if dst.kind=='void': return
    if is_struct_type(src) and is_struct_type(dst): return
    if is_float_type(dst):
        if is_float_type(src):
            if src.kind=='float' and dst.kind!='float': self.emit("    cvtss2sd %xmm0, %xmm0")
            elif src.kind!='float' and dst.kind=='float': self.emit("    cvtsd2ss %xmm0, %xmm0")
            return
        else:
            # int in rax to float
            if src.signed or type_size(src)>=8 and src.signed:
                self.emit("    cvtsi2sd %rax, %xmm0")
            else:
                # unsigned conversion approx: signed for most
                self.emit("    cvtsi2sd %rax, %xmm0")
            if dst.kind=='float': self.emit("    cvtsd2ss %xmm0, %xmm0")
            return
    if is_float_type(src):
        if is_int_type(dst) or dst.kind=='ptr':
            self.emit("    cvttsd2si %xmm0, %rax"); self.normalize_int(dst); return
        return
    # int->int/ptr
    if is_int_type(dst):
        self.normalize_int(dst)
    # ptr to int etc same

