def _cg_store_params2(self,sym,param_syms,ret_type):
    func_type=sym.type; types=[s.type for s in param_syms]
    has_sret=is_struct_type(ret_type) and type_size(ret_type)>16
    infos,gp,fp,stack=self.classify_args(types,has_sret=has_sret)
    if has_sret:
        self.emit(f"    mov %rdi, -{self.sret_offset}(%rbp)")
