        base=self.reg_save_base  # distance to end, start disp=-base
        for i,r in enumerate(REG64):
            disp=-base+i*8; self.emit(f"    mov {r}, {disp}(%rbp)")
        for i in range(8):
            disp=-base+48+i*16; self.emit(f"    movsd %xmm{i}, {disp}(%rbp)")
