        elif kind=='stack':
            src_base=16+idx*8
            if is_struct_type(s.type):
                for u in range(units):
                    self.emit(f"    mov {src_base+u*8}(%rbp), %rax")
                    self.emit(f"    mov %rax, {start_disp+u*8}(%rbp)")
            elif is_float_type(s.type):
                self.emit(f"    movsd {src_base}(%rbp), %xmm0")
                if s.type.kind=='float': self.emit(f"    movss %xmm0, {start_disp}(%rbp)")
                else: self.emit(f"    movsd %xmm0, {start_disp}(%rbp)")
            else:
                self.emit(f"    mov {src_base}(%rbp), %rax")
                self.store_reg_to_addr('%rax', f"{start_disp}(%rbp)", s.type)

