def _cg_gen_stmt(self,node):
    if node is None: return
    tag=node[0]
    if tag=='block':
        for s in node[2]: self.gen_stmt(s)
        return
    if tag=='expr_stmt':
        self.gen_expr(node[2]); return
    if tag=='decl_stmt':
        for d in node[2]:
            kind=d[0]
            if kind=='decl_local':
                sym=d[2]; init=d[3]
                if init is not None:
                    self.gen_initializer_assign(sym,init)
            elif kind=='decl_static':
                pass
        return
    if tag=='if':
        else_lbl=self.new_label(); end_lbl=self.new_label()
        self.gen_condition_jump_false(node[2], else_lbl)
        self.gen_stmt(node[3])
        if node[4] is not None:
            self.emit(f"    jmp {end_lbl}"); self.emit(f"{else_lbl}:"); self.gen_stmt(node[4]); self.emit(f"{end_lbl}:")
        else:
            self.emit(f"{else_lbl}:")
        return
    if tag=='while':
        start=self.new_label(); end=self.new_label()
        self.emit(f"{start}:"); self.gen_condition_jump_false(node[2],end)
        self.break_stack.append(end); self.continue_stack.append(start)
        self.gen_stmt(node[3]); self.break_stack.pop(); self.continue_stack.pop()
        self.emit(f"    jmp {start}"); self.emit(f"{end}:"); return
    if tag=='do':
        start=self.new_label(); end=self.new_label(); cont=self.new_label()
        self.emit(f"{start}:"); self.break_stack.append(end); self.continue_stack.append(cont); self.gen_stmt(node[2]); self.break_stack.pop(); self.continue_stack.pop()
        self.emit(f"{cont}:"); self.gen_condition_jump_true(node[3],start); self.emit(f"{end}:"); return
    if tag=='for':
        start=self.new_label(); end=self.new_label(); cont=self.new_label()
        if node[2]: self.gen_stmt(node[2])
        self.emit(f"{start}:")
        if node[3] is not None: self.gen_condition_jump_false(node[3],end)
        self.break_stack.append(end); self.continue_stack.append(cont); self.gen_stmt(node[5]); self.break_stack.pop(); self.continue_stack.pop()
        self.emit(f"{cont}:")
        if node[4] is not None: self.gen_expr(node[4])
        self.emit(f"    jmp {start}"); self.emit(f"{end}:"); return
    if tag=='switch':
        self.gen_switch(node); return
    if tag=='case':
        # inside switch body, gen_stmt for switch handles labels, but direct
        info=self.switch_stack[-1] if self.switch_stack else None
        if info is None:
            tok=node[1]; self.o.error_at(tok.file,tok.line,tok.stack,"switch expected")
        lbl=info['case_labels'].get(id(node))
        if lbl: self.emit(f"{lbl}:")
        if node[3]: self.gen_stmt(node[3])
        return
    if tag=='break':
        if not self.break_stack:
            tok=node[1]; 
            # switch also uses break_stack
            self.o.error_at(tok.file,tok.line,tok.stack,"cannot break")
        self.emit(f"    jmp {self.break_stack[-1]}"); return
    if tag=='continue':
        if not self.continue_stack:
            tok=node[1]; self.o.error_at(tok.file,tok.line,tok.stack,"cannot continue")
        self.emit(f"    jmp {self.continue_stack[-1]}"); return
    if tag=='return':
        ret_type=self.func_sym.type.base if self.func_sym.type.kind=='func' else t_int()
        expr=node[2]
        if expr is not None:
            if ret_type.kind=='void':
                self.warn_node(node[1],"void function returns a value")
                self.gen_expr(expr)
            elif is_struct_type(ret_type):
                # copy expr struct to sret or rax/rdx
                if type_size(ret_type)>16:
                    # load sret addr
                    self.emit(f"    mov -{self.sret_offset}(%rbp), %rax"); self.emit("    push %rax")
                    self.gen_expr(expr)  # addr in rax
                    self.emit("    mov %rax, %rsi"); self.emit("    pop %rdi")
                    sz=type_size(ret_type); self.emit(f"    mov ${sz}, %rdx"); self.emit("    call memcpy")
                    self.emit(f"    mov -{self.sret_offset}(%rbp), %rax")
                else:
                    self.gen_expr(expr); # addr
                    off=self.temp_offset(expr)
                    # load values from addr
                    self.emit("    mov (%rax), %rax")
                    if type_size(ret_type)>8: self.emit("    mov 8(%rax), %rdx") if False else None
                    # For >8 need second reg from address before overwriting: redo
                    # Above flawed for >8; handled by size<=8 mostly
            else:
                t=self.gen_expr(expr); self.convert(t,ret_type)
        self.emit(f"    jmp {self.return_label}"); return
    if tag=='goto':
        if not hasattr(self,'goto_refs'): self.goto_refs={}
        self.goto_refs.setdefault(node[2],[]).append(node[1])
        self.emit(f"    jmp .Llabel_{self.func_sym.name}_{node[2]}"); return
    if tag=='label':
        if not hasattr(self,'labels_defined'): self.labels_defined={}
        if node[2] in self.labels_defined:
            tok=node[1]; self.o.error_at(tok.file,tok.line,tok.stack,f"duplicate label '{node[2]}'")
        self.labels_defined[node[2]]=node[1]
        self.emit(f".Llabel_{self.func_sym.name}_{node[2]}:")
        if node[3]: self.gen_stmt(node[3])
        return
    if tag=='asm':
        txt=node[2]
        if txt:
            for line in txt.splitlines(): self.emit("    "+line)
        return
    # fallback expression
    self.gen_expr(node)

