        # Actually for do-while usage, we will handle with false jump to end alternative in code: caller expects true jump.
        return
    self.emit("    test %rax, %rax"); self.emit(f"    jne {target}")
def _cg_emit_condition_false(self,t,target):
    if is_float_type(t):
        self.emit("    xorpd %xmm1, %xmm1"); self.emit("    ucomisd %xmm1, %xmm0")
        self.emit(f"    je {target}"); self.emit(f"    jp {target}")
    else:
        self.emit("    test %rax, %rax"); self.emit(f"    je {target}")

