def _cg_gen_switch(self,node):
    expr=node[2]; body=node[3]
    end=self.new_label()
    # collect cases
    cases=[]
    def collect(n):
        if n is None: return
        if isinstance(n,tuple):
            if n[0]=='switch': return
            if n[0]=='case': cases.append(n)
            for x in n[1:]: collect(x)
        elif isinstance(n,list):
            for x in n: collect(x)
