def _cg_symbol_address(self,sym):
    if sym.storage in ('local','param'):
        off=self.local_offsets.get(id(sym), sym.offset)
        self.emit(f"    lea -{off}(%rbp), %rax")
    elif sym.storage in ('static','static_local'):
        lbl=getattr(sym,'asm_label', sym.label or sym.name)
        self.emit(f"    lea {lbl}(%rip), %rax")
    else:
        lbl=apply_leading_underscore(self.o, sym.name)
        sym.asm_label=lbl
        self.emit(f"    lea {lbl}(%rip), %rax")

def _cg_gen_lvalue(self,node):
    tag=node[0]
    if tag=='id':
        sym=node[2]; self.symbol_address(sym); return sym.type
    if tag=='unary' and node[2]=='*':
        t=self.gen_expr(node[3]); return decay(infer_type(self.p,node[3])).base if decay(infer_type(self.p,node[3])).kind=='ptr' else t_int()
    if tag=='member':
        if node[4]: # arrow
            t=self.gen_expr(node[2]) # pointer in rax
            ot=decay(infer_type(self.p,node[2])); base=ot.base
        else:
            base_t=self.gen_lvalue(node[2]); base=base_t
