        fld=find_field(base,node[3])
        if fld is None: tok=node[1]; self.o.error_at(tok.file,tok.line,tok.stack,f"field not found: {node[3]}")
        if fld.offset: self.emit(f"    add ${fld.offset}, %rax")
        return fld.type
    if tag=='index':
        # address = base + index*size
        at=infer_type(self.p,node[2]); dt=decay(at)
        elem=dt.base if dt.kind=='ptr' else t_int()
        # compute base address/value
        if at.kind=='array' and node[2][0] in ('id','member','index'):
            self.gen_lvalue(node[2]) # address of array
        else:
            self.gen_expr(node[2]) # pointer or array decay address
        self.emit("    push %rax")
        it=self.gen_expr(node[3]); self.convert(it,t_long())
        sz=type_size(elem)
        if sz>1: self.emit(f"    imul ${sz}, %rax")
        self.emit("    pop %rcx"); self.emit("    add %rcx, %rax")
        return elem
    if tag=='compound':
        # address of temp initialized
        off=self.temp_offset(node)
        typ=node[2]
        if off is not None:
            self.emit(f"    lea -{off}(%rbp), %rax")
            # initialize temp
            self.emit("    push %rax")
            self.gen_init_to_address(node[3],typ) # expects address on stack? We'll implement alternative below
            self.emit("    pop %rax"); self.emit(f"    lea -{off}(%rbp), %rax")
