def _cg_check_assign_warnings(self,tok, expr, target_type):
    if expr is None or target_type is None: return
    try: st=infer_type(self.p,expr)
    except Exception: return
    # discards qualifiers
    if target_type.kind=='ptr' and decay(st).kind=='ptr':
        src=decay(st)
        if src.base and src.base.is_const and not (target_type.base and target_type.base.is_const):
            self.warn_node(tok,"assignment discards qualifiers from pointer target type",'discarded-qualifiers')
        return
    if is_int_type(target_type) and decay(st).kind=='ptr':
        if not (expr[0]=='cast'):
            self.warn_node(tok,"assignment makes integer from pointer without a cast")
            if type_size(target_type)!=8:
                self.warn_node(tok,"cast between pointer and integer of different size")
        return
    if target_type.kind=='ptr' and is_int_type(st):
        # null constant 0 is ok
        if expr[0]=='num' and expr[2]==0: return
        if expr[0]!='cast':
            self.warn_node(tok,"assignment makes pointer from integer without a cast")
            if type_size(st)!=8:
                self.warn_node(tok,"cast between pointer and integer of different size")
        return

