                                    bit=fld.bit_offset-fld.offset*8; cur|= (v & ((1<<fld.bit_width)-1))<<bit
                                    data[off+fld.offset:off+fld.offset+sz]=cur.to_bytes(sz,'little')
                            else: fill(off+fld.offset, fld.type, val)
                return
            if t.kind=='array':
