# ---------------- ELF / archive helpers ----------------
def parse_elf_symbols_from_bytes(data):
    if len(data)<64 or data[:4]!=b'\x7fELF': raise ValueError("not elf")
    if data[4]!=2: raise ValueError("not elf64")
    e_shoff=struct.unpack_from('<Q',data,0x20)[0]
    e_shentsize,e_shnum,e_shstrndx=struct.unpack_from('<HHH',data,0x3a)
    sections=[]
    for i in range(e_shnum):
        off=e_shoff+i*e_shentsize
        if off+64>len(data): break
        name,typ,flags,addr,offset,size,link,info,align,entsize=struct.unpack_from('<IIQQQQIIQQ',data,off)
        sections.append(dict(name=name,type=typ,offset=offset,size=size,link=link,info=info,entsize=entsize))
    syms=[]
    for sec in sections:
        if sec['type'] not in (2,11): continue # SYMTAB,DYNSYM
        strsec=sections[sec['link']] if sec['link']<len(sections) else None
        if not strsec: continue
        entsize=sec['entsize'] or 24
        count=sec['size']//entsize
        for i in range(count):
            off=sec['offset']+i*entsize
            if off+24>len(data): break
            st_name,st_info,st_other,st_shndx,st_value,st_size=struct.unpack_from('<IBBHQQ',data,off)
            if st_name==0: nm=''
            else:
                soff=strsec['offset']+st_name; end=data.find(b'\0',soff)
                nm=data[soff:end].decode('utf-8','surrogateescape') if end>=0 else ''
            bind=st_info>>4; typ=st_info&0xf
            syms.append(dict(name=nm,bind=bind,type=typ,shndx=st_shndx,value=st_value,size=st_size))
    return syms

def elf_section_sizes(path):
    try:
        data=open(path,'rb').read()
        if len(data)<64 or data[:4]!=b'\x7fELF' or data[4]!=2: return {}
        e_shoff=struct.unpack_from('<Q',data,0x20)[0]
        e_shentsize,e_shnum,e_shstrndx=struct.unpack_from('<HHH',data,0x3a)
        sections=[]
        for i in range(e_shnum):
            off=e_shoff+i*e_shentsize
            name,typ,flags,addr,offset,size,link,info,align,entsize=struct.unpack_from('<IIQQQQIIQQ',data,off)
            sections.append((name,typ,size,offset))
        # shstrtab
        if e_shstrndx>=len(sections): return {}
        shstr=sections[e_shstrndx]
        res={}
        for name,typ,size,offset in sections:
            soff=shstr[3]+name; end=data.find(b'\0',soff); nm=data[soff:end].decode() if end>=0 else ''
            res[nm]=size
        return res
    except Exception:
        return {}

def parse_ar_bytes(data):
    if not data.startswith(b'!<arch>\n'): raise ValueError("not ar")
    pos=8; members=[]; longnames=b''
    while pos+60<=len(data):
        hdr=data[pos:pos+60]
        if hdr[58:60]!=b'`\n': break
        name=hdr[0:16].decode('utf-8','surrogateescape').strip()
        try: size=int(hdr[48:58].decode().strip() or '0')
        except: size=0
        content=data[pos+60:pos+60+size]
