                off=int(name[1:]); end=longnames.find(b'\n',off); disp=longnames[off:end].decode('utf-8','surrogateescape').rstrip('/') if end>=0 else name
            elif disp.endswith('/'): disp=disp[:-1]
            members.append((disp,content))
        pos+=60+size+(size&1)
    return members

def ar_format(members):
    # members: list of (name, bytes, symbols list)
    # build symbol index
    offsets=[]; sym_entries=[]
    # compute header sizes: magic + sym header/content + longnames if needed
    # Simplify names <=15 chars usually; handle long names via // member
    longnames=b''; member_name_fields=[]
    for name,data in [(m[0],m[1]) for m in members]:
        if len(name)>15 or ' ' in name:
            off=len(longnames); longnames+=name.encode()+b'/\n'; member_name_fields.append(f'/{off}')
        else:
