    try: syms=parse_elf_symbols_from_bytes(data)
    except Exception: return []
    res=[]
    for s in syms:
        if s['name'] and s['bind'] in (1,2) and s['shndx']!=0 and s['type']!=3 and s['type']!=4:
            # include weak
            res.append(s['name'])
    return res

# ---------------- Driver state ----------------
class FileEntry:
    def __init__(self,display,x=None,kind='file',libname=None):
        self.display=display; self.x=x; self.kind=kind; self.libname=libname

class Driver:
    def __init__(self,opts,argv0):
        self.opts=opts; self.argv0=argv0
        self.entries=[]
        self.artifacts=[]  # dict path, display, defined, undefined, strong
        self.c_outputs=[]  # (entry, artifact)
        self.e_buffer=[]
        self.last_pp=None
        self.tmpdir_obj=tempfile.mkdtemp(prefix='tccclone')
        self.tmp_counter=0
        self.defined_map={}  # sym -> artifact index
        self.run_args=[]
        self.deps_all=[]; self.deps_seen=set(); self.dep_first_target=None
        self.start=time.time()
    def tmp_path(self, suffix):
        self.tmp_counter+=1; return os.path.join(self.tmpdir_obj, f"tmp{self.tmp_counter}{suffix}")
    def cleanup(self):
        try:
            import shutil; shutil.rmtree(self.tmpdir_obj,ignore_errors=True)
        except Exception: pass

