def _drv_collect_defined_undefined(self):
    defined=set(self.defined_map.keys())
    # add shared library artifact symbols and archive potential symbols as defined for undefined check? For archives, potential symbols count as defined (member can be pulled)
    for art in self.artifacts:
        if art.get('kind')=='archive':
            try:
                data=open(art['path'],'rb').read(); members=parse_ar_bytes(data)
                for name,content in members: defined.update(elf_defined_symbols(content))
            except Exception: pass
        if art.get('kind')=='shared':
            try:
                data=open(art['path'],'rb').read()
                if data[:4]==b'\x7fELF':
                    for s in parse_elf_symbols_from_bytes(data):
                        if s['name'] and s['shndx']!=0: defined.add(s['name'])
            except Exception: pass
    # default libc symbols for non-nostdlib, non-static
    opts=self.opts
    if not opts.nostdlib and not opts.static and opts.action!='reloc':
        for libfile in ["/lib/x86_64-linux-gnu/libc.so.6","/lib/x86_64-linux-gnu/libm.so.6","/lib/x86_64-linux-gnu/libpthread.so.0","/lib/x86_64-linux-gnu/libdl.so.2","/lib/x86_64-linux-gnu/librt.so.1"]:
            try:
                data=open(libfile,'rb').read()
                for s in parse_elf_symbols_from_bytes(data):
                    if s['name'] and s['shndx']!=0: defined.add(s['name'].split('@')[0])
            except Exception: pass
        defined.update(['memcpy','memset','memmove','strlen','strcmp','strcpy','malloc','free','printf','fprintf','sprintf','snprintf','puts','putchar','exit','abort','__libc_start_main'])
    undefined=[]
    seen=set()
    for art in self.artifacts:
        for name in art.get('undefined',[]):
            if name not in defined and name not in seen: seen.add(name); undefined.append(name)
    return defined,undefined

def _drv_output_error_create(self,outfile):
    try:
        with open(outfile,'wb') as f: pass
    except OSError as e:
        raise TCCError(f"tcc: error: could not write '{outfile}: {e.strerror}'\n")
    if opts_is_executable(self.opts): 
        try: os.chmod(outfile,0o755)
        except Exception: pass

def opts_is_executable(opts): return opts.action in ('exe','shared','run')

def _drv_do_link(self):
    opts=self.opts
    outfile=opts.outfile or 'a.out'
    if opts.action=='reloc':
        paths=[]
        for art in self.artifacts: paths.append(art['path'])
        for e in self.entries:
            if e.kind=='lib':
                # find library path for ld -r
                cand=find_library_file(opts,e.libname)
                if cand: paths.append(cand)
