        if not paths:
            empty=self.tmp_path('.o'); asm=self.tmp_path('.s'); open(asm,'w').write('.text\n'); subprocess.run(['as','-o',empty,asm],capture_output=True)
            paths=[empty]
        r=subprocess.run(['ld','-r','-o',outfile]+paths,capture_output=True,text=True)
        if r.returncode!=0:
            raise TCCError(self._ld_error_to_tcc(r))
        if opts.verbose>=1: out_write(f"<- {outfile}\n")
