                if cand: lib_args.append(cand)
                else: lib_args.append('-l'+e.libname)
        for d in opts.libpaths: lib_args.append('-L'+d)
        cmd=ld_cmd + crt_objs + special_objs + objs + lib_args
        if libtcc: cmd.append(libtcc)
