class TCCExit(Exception):
    def __init__(self,code): self.code=code

def split_listfile(content):
    toks=[]; i=0; n=len(content); cur=''; active=False; quote=None
    while i<n:
        c=content[i]
        if quote:
            if c==quote: quote=None; i+=1; continue
            if c=='\\' and i+1<n and quote=='"': cur+=content[i+1]; i+=2; continue
            cur+=c; i+=1; continue
        if c in '"\'':
            quote=c; active=True; i+=1; continue
        if c.isspace():
            if active or cur: toks.append(cur); cur=''; active=False
            i+=1; continue
        if c=='\\' and i+1<n: cur+=content[i+1]; active=True; i+=2; continue
        cur+=c; active=True; i+=1
    if active or cur: toks.append(cur)
    return toks

def cross_m32(opts, argv0):
    if '/' in argv0:
        d=argv0.rsplit('/',1)[0]
        path=(d+'/i386-tcc') if d else '/i386-tcc'
    else:
        path='i386-tcc'
    if os.path.isfile(path) and os.access(path, os.X_OK):
        # exec with -m32 removed (first occurrence) from original argv
        args=[path]
        removed=False
        for a in sys.argv[1:]:
            if not removed and a=='-m32': removed=True; continue
            args.append(a)
        try: os.execv(path,args)
        except Exception: pass
    err_write(f"tcc: could not run '{path}'\n")
    raise TCCExit(1)

class MainParser:
    def __init__(self,opts,driver,argv0):
        self.opts=opts; self.driver=driver; self.argv0=argv0
        self.tokens=[]; self.i=0; self.early=True; self.saw_token=False; self.regular_started=False
    def missing(self, canon):
        raise TCCError(f"tcc: error: argument to '{canon}' is missing\n")
    def get_value(self, token, prefix, canon):
        rest=token[len(prefix):]
        if rest!='': return rest
        if self.i+1<len(self.tokens):
            self.i+=1; return self.tokens[self.i]
        self.missing(canon)
    def set_action(self,new_action,label):
        opts=self.opts
        if opts.action_explicit:
            opts.warn(f"{label}: overriding compiler action already specified")
        opts.action=new_action; opts.action_explicit=True
    def add_file(self,display,x=None):
        entry=FileEntry(display,x,'file')
        self.driver.entries.append(entry)
        if self.opts.action=='run':
            self.driver.run_args=self.tokens[self.i+1:]
            self.i=len(self.tokens)
            raise TCCExit(1000)  # marker handled in loop? We'll use flag instead
        return entry
    # We will implement add_file without exception in run method below

