def parse_apply_f(opts, token):
    name=token[2:]
    value=True
    if name.startswith('no-'): value=False; name=name[3:]
    known={'unsigned-char','signed-char','common','leading-underscore','ms-extensions','dollars-in-identifiers','reverse-funcargs','gnu89-inline','asynchronous-unwind-tables','test-coverage'}
    if name not in known:
        if opts.warn_unsupported: opts.warn(f"unsupported option '{token}'")
        return
    if name=='unsigned-char': opts.flags['unsigned-char']=value
    elif name=='signed-char': opts.flags['unsigned-char']=not value
    else: opts.flags[name]=value

def parse_apply_w(opts, token):
    name=token[2:]
    if name=='': return
    value=True; base=name
    if name.startswith('no-'): value=False; base=name[3:]
    # -Wno-error forms: base may be 'error' etc.
    recognized={'all','error','write-strings','unsupported','implicit-function-declaration','discarded-qualifiers'}
    check=base.split('=',1)[0]
    if check not in recognized:
        if opts.warn_unsupported: opts.warn(f"unsupported option '{token}'")
        return
    if base=='all':
        opts.warn_all=value
        if value: opts.warn_implicit=True; opts.warn_discarded=True
    elif base=='error': opts.warn_error=value
    elif base.startswith('error='):
        spec=base.split('=',1)[1]
        if spec=='all' or spec in recognized:
            if value: opts.warn_error_specific.add(spec)
            else: opts.warn_error_specific.discard(spec)
        else:
            if opts.warn_unsupported: opts.warn(f"unsupported option '{token}'")
    elif base.startswith('no-error='):
        spec=base.split('=',1)[1]
        opts.warn_error_specific.discard(spec)
    elif base=='write-strings': opts.warn_write_strings=value
    elif base=='unsupported': opts.warn_unsupported=value
    elif base=='implicit-function-declaration': opts.warn_implicit=value
    elif base=='discarded-qualifiers': opts.warn_discarded=value

def parse_wl(opts, token, mp):
    rest=token[4:]
    if not rest: return
    segs=rest.split(',')
    idx=0
    def need_value(seg):
        nonlocal idx
        if '=' in seg: return seg.split('=',1)[1]
        if idx+1<len(segs): idx+=1; return segs[idx]
        raise TCCError(f"tcc: error: argument to '-Wl,{seg}' is missing\n")
    while idx<len(segs):
        seg=segs[idx]
        if seg=='':
            idx+=1; continue
        if seg=='-nostdlib': opts.nostdlib=True
        elif seg in ('-whole-archive','--whole-archive','-no-whole-archive','--no-whole-archive','-Bsymbolic','-enable-new-dtags','-as-needed','-export-dynamic','-export-all-symbols'):
            if 'export' in seg: opts.rdynamic=True
            opts.linker_opts.append(seg)
        elif seg.startswith('-rpath='): opts.rpath.append(seg.split('=',1)[1])
        elif seg=='-rpath': opts.rpath.append(need_value(seg))
        elif seg.startswith('-soname='): opts.soname=seg.split('=',1)[1]
        elif seg=='-soname': opts.soname=need_value(seg)
        elif seg.startswith('-dynamic-linker='): opts.linker_opts.append(seg)
        elif seg.startswith('-I') and len(seg)>2: opts.linker_opts.append(seg)
        elif seg=='-I': v=need_value(seg); opts.linker_opts.append('-I'+v)
        elif any(seg.startswith(p) for p in ('-image-base=','-Ttext=','-section-alignment=','-oformat=','-init=','-fini=','-Map=','-z=')):
            opts.linker_opts.append(seg)
        elif seg in ('-init','-fini','-Map','-oformat','-image-base','-Ttext','-section-alignment','-z'):
            v=need_value(seg); opts.linker_opts.append(seg+'='+v)
        elif seg=='-O': opts.linker_opts.append(seg)
        else:
            raise TCCError(f"tcc: error: unsupported linker option '{seg}'\n")
        idx+=1

def real_main_inner(opts, driver, argv0):
    mp=MainParser(opts,driver,argv0)
    tokens=sys.argv[1:]
    mp.tokens=tokens; mp.captured=False
    # helper local add file (override method behavior)
    def add_file(display, x=None):
        e=FileEntry(display, x if x is not None else opts.current_x, 'file')
        # reset current_x after a file (unless x explicitly passed? current_x consumed)
        opts.current_x=None
        driver.entries.append(e)
        if opts.action=='run':
            driver.run_args=tokens[mp.i+1:]
            mp.captured=True
            mp.i=len(tokens)
        return e
    mp.add_file_local=add_file
    while mp.i < len(tokens):
        token=tokens[mp.i]; mp.saw_token=True
        # listfile expansion (before early handling)
        if token.startswith('@') and len(token)>1:
            try:
                with open(token[1:],'r',encoding='utf-8',errors='surrogateescape') as f: content=f.read()
            except Exception:
                raise TCCError(f"tcc: error: listfile '{token[1:]}' not found\n")
            newtoks=split_listfile(content)
            tokens[mp.i:mp.i+1]=newtoks
            if mp.i>=len(tokens): break
            continue
        if mp.early:
            # early-only handling
            if token=='--':
                mp.i+=1; continue
            if token in ('-h','--help','-?'):
                out_write(HELP_TEXT); return 0
            if token=='-hh':
                out_write(HELP2_TEXT); return 0
            if token=='-dumpversion':
                out_write("0.9.28rc\n"); return 0
            if token=='-print-search-dirs':
                opts.emit_version(); out_write(opts.print_search_dirs()); return 0
            if token=='-ar':
                return do_ar(opts, tokens[mp.i+1:], argv0)
            if token=='-B' or token.startswith('-B'):
                if token=='-B':
                    if mp.i+1>=len(tokens): raise TCCError("tcc: error: argument to '-B' is missing\n")
                    mp.i+=1; opts.bdir=tokens[mp.i]
                else: opts.bdir=token[2:]
                mp.i+=1; continue
            if token=='--version' or (token.startswith('-v') and not token.startswith('--')):
                if token=='--version': opts.verbose+=1
                else:
                    cnt=0
                    for ch in token[1:]:
                        if ch=='v': cnt+=1
                        else: break
                    opts.verbose+=cnt
                mp.i+=1; continue
            if token.startswith('-m'):
                rest=token[2:]
                mm=re.match(r'([0-9]+)',rest)
                if mm and int(mm.group(1))==32: cross_m32(opts,argv0)
                if mm and int(mm.group(1))==64:
                    mp.i+=1; continue
                # not early for other -m
            # fallthrough to regular
            mp.early=False; mp.regular_started=True
        # ---- regular parsing ----
        # cannot-parse specials
        if token in ('-h','-hh','--help','-?','-print-search-dirs'):
            raise TCCError(f"tcc: error: cannot parse {token} here\n")
        if token=='-ar':
            raise TCCError("tcc: error: cannot parse -ar here\n")
        if token=='-dumpversion':
            out_write("0.9.28rc\n"); return 0
        if token=='--':
            if opts.action=='run':
                driver.run_args=tokens[mp.i+1:]; mp.captured=True; break
            mp.i+=1; continue
        if token=='--version':
            opts.verbose+=1; mp.i+=1; continue
        if token.startswith('-v') and not token.startswith('--'):
            cnt=0
            for ch in token[1:]:
                if ch=='v': cnt+=1
                else: break
            opts.verbose+=cnt; mp.i+=1; continue
        if token.startswith('--') and token not in ('--help','--version','--param') and not token.startswith('--param'):
            raise TCCError(f"tcc: error: invalid option -- '{token}'\n")
        # -B again
        if token=='-B' or token.startswith('-B'):
            if token=='-B':
                if mp.i+1>=len(tokens): raise TCCError("tcc: error: argument to '-B' is missing\n")
                mp.i+=1; opts.bdir=tokens[mp.i]
            else: opts.bdir=token[2:]
            mp.i+=1; continue
        if token.startswith('-m'):
            rest=token[2:]
            mm=re.match(r'([0-9]+)',rest)
            if mm and int(mm.group(1))==32: cross_m32(opts,argv0)
            # other -m
            name=rest
            if name in ('ms-bitfields','no-sse'): opts.flags[name]=True
            elif name not in ('','32','64') and not mm:
                if opts.warn_unsupported: opts.warn(f"unsupported option '{token}'")
            mp.i+=1; continue
        # Wp / Wl injection
        if token.startswith('-Wp,'):
            sub=token[4:]
            if sub:
                tokens.insert(mp.i+1, sub if sub.startswith('-') else '-'+sub)
            mp.i+=1; continue
        if token.startswith('-Wl,') or token=='-Wl':
            if token.startswith('-Wl,'): parse_wl(opts,token,mp)
            mp.i+=1; continue
        # run
        if token.startswith('-run'):
            mp.set_action('run','-run')
            suffix=token[4:]
            if suffix:
                add_file(suffix, opts.current_x)
            mp.i+=1
            if mp.captured: break
            continue
        if token in ('-c','-E','-r','-shared'):
            mapping={'-c':'obj','-E':'preprocess','-r':'reloc','-shared':'shared'}
            mp.set_action(mapping[token],token)
            mp.i+=1; continue
        # dep options before MF/M
        if token=='-MF' or token.startswith('-MF'):
            opts.dep_file=mp.get_value(token,'-MF','-MF'); mp.i+=1; continue
        if token.startswith('-MMD'):
            opts.dep_mode='MMD'; mp.i+=1; continue
        if token.startswith('-MD'):
            opts.dep_mode='MD'; mp.i+=1; continue
        if token=='-MM': opts.dep_mode='MM'; mp.i+=1; continue
        if token=='-M': opts.dep_mode='M'; mp.i+=1; continue
        # bench / warnings disable
        if token=='-bench': opts.bench=True; mp.i+=1; continue
        if token=='-w': opts.warnings_disabled=True; mp.i+=1; continue
        if token.startswith('-bt'):
            rest=token[3:]; mnum=re.match(r'[0-9]+',rest); opts.bt=int(mnum.group(0)) if mnum else 1; mp.i+=1; continue
        if token=='-b': opts.bcheck=True; opts.bt=1 if opts.bt is None else opts.bt; opts.debug=1; mp.i+=1; continue
        if token.startswith('-g'): opts.debug=1; mp.i+=1; continue
        if token.startswith('-P'):
            opts.p_mode=2 if token[2:]=='1' else 1; mp.i+=1; continue
        if token.startswith('-dt'):
            opts.dt=True; mp.i+=1; continue
        if token.startswith('-dM'):
            opts.dM=True; mp.i+=1; continue
        if token.startswith('-dD'):
            opts.dD=True; mp.i+=1; continue
        if token.startswith('-d'):
            mp.i+=1; continue
        if token.startswith('-O'):
            rest=token[2:]
            if rest=='': opts.optimize=1
            else:
                mnum=re.match(r'[0-9]+',rest)
                if mnum: opts.optimize=int(mnum.group(0))
                else: opts.optimize=1
            mp.i+=1; continue
        if token.startswith('-std'):
            val=token[4:]
            if val.startswith('='): val=val[1:]
            opts.std=val; mp.i+=1; continue
        if token=='-pthread':
            opts.pthread=True; mp.i+=1; continue
        if token=='-nostdinc': opts.nostdinc=True; mp.i+=1; continue
        if token=='-nostdlib': opts.nostdlib=True; mp.i+=1; continue
        if token=='-static': opts.static=True; mp.i+=1; continue
        if token=='-rdynamic': opts.rdynamic=True; mp.i+=1; continue
        if token in ('-pie','-s','-C','-pipe','-pedantic','-traditional'): mp.i+=1; continue
        # argument options ordered
        if token.startswith('-include'):
            val=mp.get_value(token,'-include','-include'); opts.include_files.append(val); mp.i+=1; continue
        if token.startswith('-isystem'):
            val=mp.get_value(token,'-isystem','-isystem'); opts.isystem.append(val); mp.i+=1; continue
        if token.startswith('-soname'):
            val=mp.get_value(token,'-soname','-soname'); opts.soname=val; mp.i+=1; continue
        if token.startswith('-rstdin'):
            val=mp.get_value(token,'-rstdin','-rstdin'); opts.rstdin=val; mp.i+=1; continue
        if token.startswith('-arch'):
            val=mp.get_value(token,'-arch','-arch'); mp.i+=1; continue
        if token.startswith('--param'):
            val=mp.get_value(token,'--param','--param'); mp.i+=1; continue
        if token.startswith('-I'):
            val=mp.get_value(token,'-I','-I'); opts.includes.append(val); mp.i+=1; continue
