    if opts.action=='obj':
        if any(e.kind=='lib' for e in driver.entries):
            raise TCCError("tcc: error: cannot specify libraries with -c\n")
        filecount=len([e for e in driver.entries if e.kind=='file'])
        if opts.outfile and filecount>1:
            raise TCCError("tcc: error: cannot specify output file with -c many files\n")
    if opts.action=='preprocess' and opts.outfile:
        # validate writable early
        try:
            with open(opts.outfile,'wb') as f: pass
        except OSError:
            raise TCCError(f"tcc: error: could not write '{opts.outfile}'\n")
