    for entry in list(driver.entries):
        if entry.kind=='lib': driver.process_library(entry)
        else: driver.process_file(entry)
    result=0
    if opts.action=='preprocess':
        driver.flush_e()
    elif driver.effective_dep_only():
        target=dep_target_name(opts,driver.entries)
        txt=format_deps(target,driver.deps_all)
