            except OSError:
                err_write(f"tcc: error: could not open '{opts.dep_file}'\n")
        else:
            out_write(txt)
    elif opts.action=='obj':
        driver.write_c_outputs()
    elif opts.action in ('reloc','shared','exe','run'):
        result=driver.do_link()
    if opts.bench:
        driver.bench_output()
    return result

