def main():
    opts=Options(); driver=Driver(opts,sys.argv[0])
    try:
        code=real_main_inner(opts,driver,sys.argv[0])
        driver.cleanup(); return code
    except TCCExit as e:
        driver.cleanup(); return e.code
    except TCCError as e:
        # version emission for regular errors
        try: opts.emit_version()
        except Exception: pass
        # Preprocess buffering/error newline handling
        is_pp = (opts.action=='preprocess')
        if is_pp:
            buf=''.join(driver.e_buffer); driver.e_buffer=[]
            if opts.dM and driver.last_pp is not None:
                try: buf+=driver._dm_text(driver.last_pp)
                except Exception: pass
            msg=e.msg or ''
            if msg.startswith("tcc: error: could not write '") and opts.outfile:
                # stdout newline only
                if buf and not opts.outfile:
                    pass
                out_write("\n")
            elif msg.startswith('tcc: error:'):
                if opts.outfile:
                    # write buffered to file if possible
                    try:
                        with open(opts.outfile,'w',encoding='utf-8',errors='surrogateescape') as f: f.write(buf)
                    except Exception: pass
                else:
                    out_write(buf); out_write("\n")
            else:
                if opts.outfile:
                    try:
                        with open(opts.outfile,'w',encoding='utf-8',errors='surrogateescape') as f: f.write(buf)
                    except Exception: pass
                else:
                    out_write(buf)
        if e.msg:
            err_write(e.msg if e.msg.endswith('\n') else e.msg+'\n')
        driver.cleanup(); return e.code
    except BrokenPipeError:
        return 1

if __name__=='__main__':
    sys.exit(main())
